const TEST_BANK_PYTHON = [

  // ════════════════════════════════════════════════════════════════
  //  UNIDAD 1 — Elementos de un programa Python
  // ════════════════════════════════════════════════════════════════
  { concept_id:"py_u1_q1", unit:1, question:"¿Cuál es la diferencia principal entre Python 2 y Python 3?", options:["Python 3 es más lento, concepto diferente al que se describe en esta pregunta","Python 3 no es compatible con Python 2: print() es función","Python 2 soporta más librerías, concepto diferente al que se describe en esta pregunta","Python 3 es solo para Windows, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Python 2 llegó a su fin en 2020. Python 3 introdujo print(), división real (5/2=2.5), str=Unicode, async nativo, anotaciones de tipo y mucho más.", noShuffle:false },
  { concept_id:"py_u1_q2", unit:1, question:"¿Cómo se muestra texto por pantalla en Python 3?", options:["console.log('Hola')","echo 'Hola'","print('Hola')","System.out.println('Hola')"], correct:2, explanation:"print() es la función estándar de Python 3 para salida. print('a','b',sep='-',end='!') → 'a-b!'", noShuffle:false },
  { concept_id:"py_u1_q3", unit:1, question:"¿Cuál es el tipo de una variable en Python si se le asigna 3.14?", options:["int","decimal","float","double"], correct:2, explanation:"En Python: 3.14 → float, 3 → int, '3.14' → str, 3+2j → complex. type(3.14) devuelve <class 'float'>.", noShuffle:false },
  { concept_id:"py_u1_q4", unit:1, question:"¿Cómo se escribe un comentario en Python?", options:["// Comentario","/* Comentario */","# Comentario","<!-- Comentario -->"], correct:2, explanation:"Los comentarios de línea en Python usan #. Los docstrings (\"\"\"...\"\"\") son strings especiales para documentar funciones y clases.", noShuffle:false },
  { concept_id:"py_u1_q5", unit:1, question:"¿Qué tipo de lenguaje es Python respecto al tipado?", options:["Estáticamente tipado como Java","Dinámicamente tipado: el tipo se determina en tiempo de ejecución","Sin tipado: todos los valores son strings","Fuertemente tipado con tipos declarados obligatorios"], correct:1, explanation:"Python es dinámicamente tipado (el tipo varía) pero fuertemente tipado (no hace coerción implícita entre tipos incompatibles: '3'+3 lanza TypeError).", noShuffle:false },
  { concept_id:"py_u1_q6", unit:1, question:"¿Cómo se comprueba el tipo de una variable en Python?", options:["typeof(variable)","variable.type","type(variable)","variable.class"], correct:2, explanation:"type(x) devuelve el tipo. isinstance(x, int) devuelve True/False. Para tipos más complejos, isinstance es preferible.", noShuffle:false },
  { concept_id:"py_u1_q7", unit:1, question:"¿Cuál es el resultado de 5 // 2 en Python?", options:["2.5","2","3","2.0"], correct:1, explanation:"// es la división entera (floor division) en Python. 5//2=2. -5//2=-3 (redondea hacia abajo, no hacia cero).", noShuffle:false },
  { concept_id:"py_u1_q8", unit:1, question:"¿Qué significa que Python usa indentación para la estructura del código?", options:["Los bloques de código se delimitan con {} como en JS","Los bloques se definen por el nivel de sangría (espacios o tabs) en lugar de llaves","La indentación es solo estética, no afecta al funcionamiento","Python requiere 4 tabs de indentación obligatoriamente"], correct:1, explanation:"Python usa el whitespace como sintaxis. El PEP 8 recomienda 4 espacios. Mezclar tabs y espacios da IndentationError.", noShuffle:false },
  { concept_id:"py_u1_q9", unit:1, question:"¿Cómo se pide una entrada al usuario en Python?", options:["readline()","input('Mensaje: ')","read()","prompt('Mensaje: ')"], correct:1, explanation:"input() siempre devuelve un string. Para número: int(input('Número: ')). raw_input() era de Python 2.", noShuffle:false },
  { concept_id:"py_u1_q10", unit:1, question:"¿Cuál es el resultado de 2 ** 8 en Python?", options:["16","256","28","512"], correct:1, explanation:"** es el operador de exponenciación en Python: 2**8 = 256. Equivalente a Math.pow(2,8) en otros lenguajes.", noShuffle:false },
  { concept_id:"py_u1_q11", unit:1, question:"¿Qué es el PEP 8?", options:["Una versión de Python, concepto diferente al que se describe en esta pregunta","La guía de estilo oficial de Python: indentación, nombres de variables","Un gestor de paquetes para Python, concepto diferente al que se describe en esta pregunta","Una librería estándar de Python, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"PEP 8 es la guía de estilo de Python. snake_case para variables/funciones, UPPER_CASE para constantes, CamelCase para clases.", noShuffle:false },
  { concept_id:"py_u1_q12", unit:1, question:"¿Cuál es la diferencia entre = y == en Python?", options:["Son lo mismo, concepto diferente al que se describe en esta pregunta","= asigna un valor a una variable; == compara dos valores y devuelve True/False","== asigna; = compara, concepto diferente al que se describe en esta pregunta","= es para strings; == para números, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"= asignación: x = 5. == comparación: x == 5 → True. También: !=, <, >, <=, >=, is (identidad), in (pertenencia).", noShuffle:false },
  { concept_id:"py_u1_q13", unit:1, question:"¿Qué son las f-strings en Python (disponibles desde Python 3.6)?", options:["Funciones que devuelven strings","Strings que permiten interpolación de expresiones: f'Hola {nombre}, tienes {edad} años'","Un tipo especial de string inmutable","Strings de formato para fechas"], correct:1, explanation:"f-strings: f'{expresion}'. Son más rápidas y legibles que % o .format(). Permiten expresiones completas: f'{2**10}' → '1024'.", noShuffle:false },
  { concept_id:"py_u1_q14", unit:1, question:"¿Qué hace la función len() en Python?", options:["Devuelve el tipo del objeto","Devuelve la longitud (número de elementos) de una secuencia (string, lista, tupla, diccionario...)","Hace la lista más larga","Devuelve el valor numérico de un objeto"], correct:1, explanation:"len('hola')→4, len([1,2,3])→3, len({'a':1})→1 (claves). len(None) lanza TypeError.", noShuffle:false },
  { concept_id:"py_u1_q15", unit:1, question:"¿Cómo se convierte un string a entero en Python?", options:["int('42')","str.toInt()","integer('42')","'42'.asInt()"], correct:0, explanation:"int('42')→42. float('3.14')→3.14. str(42)→'42'. Si el string no es un número válido, lanza ValueError.", noShuffle:false },
  { concept_id:"py_u1_q16", unit:1, question:"¿Cómo se importa un módulo en Python?", options:["#include <modulo>","require('modulo')","import modulo","using modulo"], correct:2, explanation:"import modulo: acceso con modulo.funcion(). from modulo import funcion: importa directamente. import modulo as m: alias.", noShuffle:false },
  { concept_id:"py_u1_q17", unit:1, question:"¿Qué hace el operador % en Python cuando se usa con strings?", options:["Calcula el módulo de una cadena, concepto diferente al que se describe en esta pregunta","Formato de string antiguo: 'Hola %s, tienes %d años' % ('Ana'","Repite el string un número de veces, concepto diferente al que se describe en esta pregunta","Comprueba si un substring está en el string"], correct:1, explanation:"El % de string es la forma antigua de formatear (similar a C printf). .format() y f-strings son más modernas y preferibles.", noShuffle:false },
  { concept_id:"py_u1_q18", unit:1, question:"¿Qué es None en Python?", options:["El número 0, concepto diferente al que se describe en esta pregunta","El equivalente a null/undefined: ausencia de valor, objeto especial de tipo NoneType","Un string vacío, concepto diferente al que se describe en esta pregunta","False en un contexto booleano, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"None es el valor nulo de Python. type(None) → NoneType. Se comprueba con 'is None', no con '== None'.", noShuffle:false },
  { concept_id:"py_u1_q19", unit:1, question:"¿Cuáles son los valores falsy en Python?", options:["Solo False y None","False, None, 0, 0.0, '', [], {}, set(), cualquier objeto vacío","Solo False","Solo 0 y False"], correct:1, explanation:"Falsy: False, None, 0, 0.0, 0j, '', [], (), {}, set(), frozenset(). Truthy: cualquier otro valor. bool([]) → False, bool([0]) → True.", noShuffle:false },
  { concept_id:"py_u1_q20", unit:1, question:"¿Qué hace print(end='') en Python?", options:["Termina el programa, concepto diferente al que se describe en esta pregunta","Cambia el carácter de fin de línea; por defecto print añade \\n al final","Imprime el string al revés, concepto diferente al que se describe en esta pregunta","Formatea la salida como HTML, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"print('a', end=''); print('b', end='') → 'ab' en la misma línea. sep=',' cambia el separador entre argumentos.", noShuffle:false },
  { concept_id:"py_u1_q21", unit:1, question:"¿Qué hace 'a' * 3 en Python?", options:["Error de tipo, concepto diferente al que se describe en esta pregunta","'aaa' (repite el string 3 veces)","3, concepto diferente al que se describe en esta pregunta","'a3', concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"El operador * con strings repite la cadena. 'ab'*3 → 'ababab'. [1,2]*2 → [1,2,1,2] con listas.", noShuffle:false },
  { concept_id:"py_u1_q22", unit:1, question:"¿Cuál es el nombre del gestor de paquetes oficial de Python?", options:["npm","conda","pip","poetry"], correct:2, explanation:"pip install paquete. pip install -r requirements.txt. pip freeze > requirements.txt. Conda y Poetry son alternativas.", noShuffle:false },
  { concept_id:"py_u1_q23", unit:1, question:"¿Qué es un entorno virtual (virtualenv/venv) en Python?", options:["Un sandbox de ejecución segura, concepto diferente al que se describe en esta pregunta","Un entorno aislado con sus propias dependencias y versión de Python","Una máquina virtual para ejecutar Python, concepto diferente al que se describe en esta pregunta","Un entorno de desarrollo integrado, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"python -m venv .venv. .venv/bin/activate (Linux/Mac) o .venv\\Scripts\\activate (Windows). Permite versiones de paquetes distintas por proyecto.", noShuffle:false },
  { concept_id:"py_u1_q24", unit:1, question:"¿Qué significa la expresión 'a if condición else b' en Python?", options:["Un bucle condicional, concepto diferente al que se describe en esta pregunta","El operador ternario de Python: evalúa condición; si True devuelve a","Una excepción condicional, concepto diferente al que se describe en esta pregunta","Una forma especial de importar, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Ternario Python: resultado = 'par' if n % 2 == 0 else 'impar'. Equivale al condition ? a : b de JS.", noShuffle:false },
  { concept_id:"py_u1_q25", unit:1, question:"¿Para qué se usa el guion bajo (_) en Python?", options:["Solo para variables privadas, concepto diferente al que se describe en esta pregunta","Como variable desechable (_, __ ), para separar dígitos (1_000_000)","Es un operador especial, concepto diferente al que se describe en esta pregunta","Solo como separador visual en números, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Usos: _ = variable que no necesito, _privada = convención privada, __mangling = name mangling, 1_000_000 = separador de dígitos (ES legible).", noShuffle:false },
  { concept_id:"py_u1_q26", unit:1, question:"¿Cuál es la diferencia entre los operadores 'is' e '==' en Python?", options:["Son sinónimos perfectos, concepto diferente al que se describe en esta pregunta","== compara valores; is compara identidad (si son el mismo objeto en memoria)","is es más rápido que ==, concepto diferente al que se describe en esta pregunta","== solo funciona con números, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"is: identidad de objeto (misma dirección en memoria). == : igualdad de valor. Para singletons (None, True, False): usar 'is'. Para valores: usar ==.", noShuffle:false },
  { concept_id:"py_u1_q27", unit:1, question:"¿Qué hace la función range(start, stop, step)?", options:["Crea una lista de números del start al stop, concepto diferente al que se describe en esta pregunta","Genera una secuencia lazy de números desde start (incl.) hasta stop (excl.) con incremento step","Devuelve un número aleatorio en el rango, concepto diferente al que se describe en esta pregunta","Hace un bucle de start a stop veces, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"range(5)→0-4. range(2,10,2)→2,4,6,8. Es lazy (no crea la lista en memoria). list(range(5))→[0,1,2,3,4].", noShuffle:false },
  { concept_id:"py_u1_q28", unit:1, question:"¿Cómo se concatenan dos strings en Python?", options:["'a'.concat('b')","'a' + 'b' o f'{a}{b}'","str.join(['a','b'])","'a' & 'b'"], correct:1, explanation:"+ concatena strings: 'Hola' + ' Mundo'. f-strings son más eficientes para muchas concatenaciones. ''.join([lista]) para unir listas de strings.", noShuffle:false },
  { concept_id:"py_u1_q29", unit:1, question:"¿Cómo funciona la asignación múltiple en Python?", options:["No existe en Python, si bien existen aproximaciones relacionadas","a = b = c = 5 (mismo valor) o a, b, c = 1, 2, 3 (desestructuración)","a,b = 1,2,3 es válido aunque sobren valores, concepto diferente al que se describe en esta pregunta","Solo con números enteros, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Desempaquetado: a, b = 1, 2. Swap en una línea: a, b = b, a. Rest: a, *b = [1,2,3,4] → a=1, b=[2,3,4].", noShuffle:false },
  { concept_id:"py_u1_q30", unit:1, question:"¿Qué operadores lógicos existen en Python?", options:["&&, ||, !","and, or, not","AND, OR, NOT","&, |, ~"], correct:1, explanation:"Python usa palabras: and, or, not. No &&, ||, !. Tienen short-circuit evaluation igual que JS.", noShuffle:false },
  { concept_id:"py_u1_q31", unit:1, question:"¿Cuál es el nombre del intérprete interactivo de Python?", options:["PythonShell, concepto diferente al que se describe en esta pregunta","IDLE nativa, concepto diferente al que se describe en esta pregunta","Python REPL (Read-Eval-Print Loop) o el intérprete interactivo (comando python o python3)","PyShell, concepto diferente al que se describe en esta pregunta"], correct:2, explanation:"REPL: escribes expresiones y ves resultados inmediatamente. IPython y Jupyter Notebook son REPLs mejorados muy populares.", noShuffle:false },
  { concept_id:"py_u1_q32", unit:1, question:"¿Qué hace la función abs(-7) en Python?", options:["-7","7","0","Error"], correct:1, explanation:"abs() devuelve el valor absoluto. abs(-7)=7. También funciona con complejos: abs(3+4j)=5.0 (módulo).", noShuffle:false },
  { concept_id:"py_u1_q33", unit:1, question:"¿Cómo se comprueba si un elemento está en una lista o string en Python?", options:["lista.contains(elemento)","elemento in lista","lista.includes(elemento)","find(lista, elemento)"], correct:1, explanation:"'in' y 'not in' son operadores de pertenencia. 'a' in 'hola' → False. 3 in [1,2,3] → True. También funciona con diccionarios (comprueba claves).", noShuffle:false },
  { concept_id:"py_u1_q34", unit:1, question:"¿Cuál es el tipo de datos para números enteros grandes en Python?", options:["longint, concepto diferente al que se describe en esta pregunta","bigint, concepto diferente al que se describe en esta pregunta","int (Python int es de precisión arbitraria, sin límite)","int64, concepto diferente al que se describe en esta pregunta"], correct:2, explanation:"Python int no tiene límite de tamaño (a diferencia de C/Java). Puede almacenar números con millones de dígitos, limitado solo por la RAM.", noShuffle:false },
  { concept_id:"py_u1_q35", unit:1, question:"¿Qué hace la función round(3.14159, 2)?", options:["Devuelve 3.14","Devuelve 3","Devuelve 3.15","Devuelve 4"], correct:0, explanation:"round(n, decimales). round(3.14159,2)→3.14. round(3.5)→4 (pero round(2.5)→2, banker's rounding). round(314159, -3)→314000.", noShuffle:false },
  { concept_id:"py_u1_q36", unit:1, question:"¿Cuál es la forma correcta de escribir una cadena multilínea en Python?", options:["'línea1 \\n línea2', concepto diferente al que se describe en esta pregunta",  "\"\"\"línea1\nlínea2\"\"\"  o  '''línea1\nlínea2'''","'línea1' + 'línea2', concepto diferente al que se describe en esta pregunta","multilínea('línea1','línea2'), concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Las triple-quoted strings (\"\"\") son multilínea y se usan también como docstrings para documentar funciones y clases.", noShuffle:false },
  { concept_id:"py_u1_q37", unit:1, question:"¿Qué hace chr(65) en Python?", options:["Devuelve el número 65, concepto diferente al que se describe en esta pregunta","Devuelve 'A' (el carácter con código ASCII/Unicode 65)","Convierte el número a hexadecimal, concepto diferente al que se describe en esta pregunta","Crea un nuevo carácter en el sistema, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"chr(65)='A'. ord('A')=65. Juntos, chr y ord permiten convertir entre caracteres y sus códigos Unicode.", noShuffle:false },
  { concept_id:"py_u1_q38", unit:1, question:"¿Cómo se verifica el número de versión de Python desde la línea de comandos?", options:["python --info, concepto diferente al que se describe en esta pregunta","python --version o python -V","python.version, concepto diferente al que se describe en esta pregunta","check python, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"python3 --version (o python --version). Desde Python: import sys; print(sys.version). sys.version_info para comparación numérica.", noShuffle:false },
  { concept_id:"py_u1_q39", unit:1, question:"¿Qué es el duck typing en Python?", options:["Un tipo especial de herencia, concepto diferente al que se describe en esta pregunta","Si un objeto tiene los métodos/atributos necesarios, se puede usar aunque no sea de la clase específica ('if it walks like a duck...')","Un sistema de tipado estricto, que aunque es una herramienta util, no corresponde a esta definicion","La conversión implícita entre tipos, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Duck typing: Python no comprueba el tipo, sino si el objeto tiene el comportamiento requerido. Base del polimorfismo en Python sin herencia obligatoria.", noShuffle:false },
  { concept_id:"py_u1_q40", unit:1, question:"¿Qué hace el módulo 'math' de Python?", options:["Hace operaciones con cadenas, concepto diferente al que se describe en esta pregunta","Provee funciones matemáticas avanzadas: math.sqrt(), math.log(), math.pi","Gestiona matrices y álgebra lineal, concepto diferente al que se describe en esta pregunta","Es un módulo de estadística, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"import math. math.pi=3.14..., math.e=2.71..., math.sqrt(4)=2.0, math.factorial(5)=120, math.log(8,2)=3.0.", noShuffle:false },
  { concept_id:"py_u1_q41", unit:1, question:"¿Cuál es la diferencia entre 'print' en Python 2 y Python 3?", options:["No hay diferencia, aunque algunos enfoques establecen matices al respecto","En Python 2, print es una declaración (print 'Hola'); en Python 3","En Python 3, print está deprecado, concepto diferente al que se describe en esta pregunta","Python 2 no tenía print, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Esta es una de las incompatibilidades principales entre Python 2 y 3. En Python 2: from __future__ import print_function permite usar la función.", noShuffle:false },
  { concept_id:"py_u1_q42", unit:1, question:"¿Qué es la Zen of Python y cómo se accede a ella?", options:["Un framework de meditación, concepto diferente al que se describe en esta pregunta","Una colección de 19 principios de diseño del lenguaje Python (PEP 20)","El manual oficial de Python, concepto diferente al que se describe en esta pregunta","Una lista de PEPs aprobados, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"import this imprime el Zen. Algunos principios: 'Beautiful is better than ugly', 'Explicit is better than implicit', 'Simple is better than complex'.", noShuffle:false },

  // ════════════════════════════════════════════════════════════════
  //  UNIDAD 2 — Estructuras de control
  // ════════════════════════════════════════════════════════════════
  { concept_id:"py_u2_q1", unit:2, question:"¿Cuál es la estructura de un bloque if-elif-else en Python?", options:["if(condición){ }else if(c){ }else{ }","if condición:\n    ...\nelif condición2:\n    ...\nelse:\n    ...","if condición then: ... elif ... end","if condición; elif condición2; else;"], correct:1, explanation:"Python no usa llaves ni paréntesis obligatorios. La indentación define los bloques. elif (no else if) para condiciones adicionales.", noShuffle:false },
  { concept_id:"py_u2_q2", unit:2, question:"¿Cuál es la diferencia entre 'while' y 'for' en Python?", options:["Son idénticos, concepto diferente al que se describe en esta pregunta","while repite mientras una condición sea True; for itera sobre un iterable (lista, range, string...)","for solo funciona con números, concepto diferente al que se describe en esta pregunta","while no tiene else, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"for x in iterable es el bucle idiomático de Python. while para repetición con condición dinámica. Ambos aceptan else (se ejecuta si no hubo break).", noShuffle:false },
  { concept_id:"py_u2_q3", unit:2, question:"¿Para qué sirve 'break' dentro de un bucle Python?", options:["Sale del programa completo","Sale del bucle actual inmediatamente","Salta a la siguiente iteración","Reinicia el bucle desde el principio"], correct:1, explanation:"break sale del bucle sin ejecutar el bloque else. continue salta al siguiente ciclo. pass no hace nada (placeholder).", noShuffle:false },
  { concept_id:"py_u2_q4", unit:2, question:"¿Qué hace el bloque 'else' de un bucle for o while en Python?", options:["Siempre se ejecuta al final del bucle","Se ejecuta SOLO si el bucle terminó normalmente (sin break)","Es obligatorio en todos los bucles","Se ejecuta si la condición del bucle fue siempre False"], correct:1, explanation:"El else del bucle es único en Python: for x in lista: ... else: print('sin break'). Si hay break, el else no se ejecuta.", noShuffle:false },
  { concept_id:"py_u2_q5", unit:2, question:"¿Cómo se itera sobre los índices y valores de una lista al mismo tiempo?", options:["for i,v in lista.pairs()","for i, v in enumerate(lista)","for i in range(len(lista)), lista[i]","lista.forEach((i,v)=>{})"], correct:1, explanation:"enumerate(lista) genera tuplas (índice, valor). enumerate(lista, start=1) para empezar desde 1.", noShuffle:false },
  { concept_id:"py_u2_q6", unit:2, question:"¿Qué hace la función zip() en Python?", options:["Comprime archivos","Combina varios iterables en tuplas de elementos pareados: zip([1,2],[a,b])→(1,'a'),(2,'b')","Comprime una lista en un elemento","Agrupa elementos iguales de una lista"], correct:1, explanation:"zip para iterar múltiples listas en paralelo: for nombre, nota in zip(nombres, notas). dict(zip(claves,valores)) crea un diccionario.", noShuffle:false },
  { concept_id:"py_u2_q7", unit:2, question:"¿Cuándo se usa la instrucción 'pass' en Python?", options:["Para terminar una función, concepto diferente al que se describe en esta pregunta","Como bloque vacío cuando la sintaxis requiere un cuerpo pero no se necesita código","Para pausar la ejecución, concepto diferente al que se describe en esta pregunta","Para saltar a la siguiente iteración, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"pass es un placeholder: class Vacia: pass, if cond: pass (TO-DO). A diferencia de continue o break, pass no hace nada.", noShuffle:false },
  { concept_id:"py_u2_q8", unit:2, question:"¿Cuál es el equivalente Python del switch-case de otros lenguajes?", options:["switch-case (existe desde Python 3.10 como match-case)","Solo con if-elif-else, concepto diferente al que se describe en esta pregunta","No existe en Python, si bien existen aproximaciones relacionadas","select-case, concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"Python 3.10 introdujo match-case (structural pattern matching): match valor: case 1: ... case 2: ... case _: (default).", noShuffle:false },
  { concept_id:"py_u2_q9", unit:2, question:"¿Cómo se itera sobre las claves y valores de un diccionario?", options:["for k,v in dict.items()","for k,v in dict.pairs()","for k in dict.keys(), dict[k]","dict.forEach((k,v)=>{})"], correct:0, explanation:"dict.items() → pares (clave,valor). dict.keys() → claves. dict.values() → valores. Todos son vistas (actualizadas si el dict cambia).", noShuffle:false },
  { concept_id:"py_u2_q10", unit:2, question:"¿Qué es una comprensión de listas (list comprehension) en Python?", options:["Un método para entender listas complejas","Sintaxis compacta para crear listas: [expresion for elemento in iterable if condicion]","Una lista que incluye su propia documentación","Un tipo especial de lista inmutable"], correct:1, explanation:"[x**2 for x in range(10) if x%2==0] → [0,4,16,36,64]. Más eficiente y legible que un bucle for con append().", noShuffle:false },
  { concept_id:"py_u2_q11", unit:2, question:"¿Cuál es la diferencia entre una comprensión de listas [] y una expresión generadora ()?", options:["Son idénticos, concepto diferente al que se describe en esta pregunta","La lista crea todos los elementos en memoria a la vez; el generador es lazy (calcula bajo demanda)","() crea tuplas, no generadores, concepto diferente al que se describe en esta pregunta","Los generadores son más lentos siempre, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"(x**2 for x in range(1000000)) es un generador: no usa memoria hasta que se consumen los elementos. Para grandes cantidades de datos, preferible.", noShuffle:false },
  { concept_id:"py_u2_q12", unit:2, question:"¿Qué hace continue en un bucle Python?", options:["Sale del bucle actual, concepto diferente al que se describe en esta pregunta","Salta el resto del cuerpo del bucle para esa iteración y pasa a la siguiente","Reinicia el bucle desde cero, concepto diferente al que se describe en esta pregunta","Pausa el bucle por 1 segundo, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"continue equivale al continue de JS/Java. El bloque else del bucle SÍ se ejecuta aunque haya continue (pero no con break).", noShuffle:false },
  { concept_id:"py_u2_q13", unit:2, question:"¿Qué hace reversed(lista) en Python?", options:["Invierte la lista original in-place, concepto diferente al que se describe en esta pregunta","Devuelve un iterador que recorre la lista en orden inverso sin modificarla","Ordena la lista en orden descendente, concepto diferente al que se describe en esta pregunta","Devuelve el último elemento, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"reversed() devuelve un iterador inverso sin modificar el original. lista.reverse() modifica in-place. lista[::-1] crea una copia invertida.", noShuffle:false },
  { concept_id:"py_u2_q14", unit:2, question:"¿Cómo se itera sobre dos listas en paralelo en Python?", options:["parallel_for(lista1, lista2)","for a, b in zip(lista1, lista2)","for i in range(len(lista1)): a=lista1[i]; b=lista2[i]","Ambos b y c son válidos"], correct:3, explanation:"zip() es la forma idiomática y elegante. El bucle con índices funciona pero es menos pythónico. zip_longest (itertools) si las listas tienen distinto tamaño.", noShuffle:false },
  { concept_id:"py_u2_q15", unit:2, question:"¿Cuál es la forma pythónica de iterar sobre los elementos de una lista?", options:["for i in range(len(lista)): item = lista[i]","for item in lista:","while len(lista) > 0: item = lista.pop()","lista.forEach(item => ...)"], correct:1, explanation:"'for item in lista' es el estilo idiomático de Python (duck typing). El bucle con range+len es válido pero menos elegante.", noShuffle:false },
  { concept_id:"py_u2_q16", unit:2, question:"¿Qué es el walrus operator (:=) introducido en Python 3.8?", options:["Un operador para asignar valores a diccionarios, concepto diferente al que se describe en esta pregunta","El operador de asignación en expresión: permite asignar Y usar el valor en la misma expresión","Un operador de comparación alternativo al ==, concepto diferente al que se describe en esta pregunta","Un decorador de funciones, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"while chunk := f.read(8192): procesar(chunk). Evita duplicar llamadas. if (n := calcular()) > 0: usar(n).", noShuffle:false },
  { concept_id:"py_u2_q17", unit:2, question:"¿Qué hace la función sorted() en Python?", options:["Ordena la lista original in-place","Devuelve UNA NUEVA lista ordenada sin modificar el original","Comprueba si una lista está ordenada","Ordena todos los tipos de datos del mismo modo"], correct:1, explanation:"sorted(iterable, key=fn, reverse=True) → nueva lista. lista.sort() modifica in-place y devuelve None. sorted admite cualquier iterable.", noShuffle:false },
  { concept_id:"py_u2_q18", unit:2, question:"¿Cómo se crea un bucle infinito en Python?", options:["while (True)","while True:","loop:","for ever:"], correct:1, explanation:"while True: es el bucle infinito estándar en Python (sin paréntesis). Se sale con break o con excepciones.", noShuffle:false },
  { concept_id:"py_u2_q19", unit:2, question:"¿Qué es una comprensión de diccionario en Python?", options:["Un método para documentar diccionarios","Sintaxis compacta para crear diccionarios: {k:v for k,v in items if condicion}","Un tipo especial de dict","No existen comprensiones de diccionario"], correct:1, explanation:"{clave:valor for item in iterable}. Ej: {p:p**2 for p in range(5)} → {0:0,1:1,2:4,3:9,4:16}.", noShuffle:false },
  { concept_id:"py_u2_q20", unit:2, question:"¿Cuál es la diferencia entre 'any()' y 'all()' en Python?", options:["Son idénticas, concepto diferente al que se describe en esta pregunta","any(iterable)→True si al menos un elemento es truthy; all(iterable)→True solo si TODOS son truthy","all() es más rápida, concepto diferente al que se describe en esta pregunta","any() solo funciona con booleanos, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"any([False,True,False])→True. all([True,True,False])→False. any([])→False. all([])→True (vacío: vacuously true). Ambas con short-circuit.", noShuffle:false },
  { concept_id:"py_u2_q21", unit:2, question:"¿Qué hace 'assert condición, mensaje' en Python?", options:["Muestra el mensaje si la condición es True","Lanza AssertionError con el mensaje si la condición es False","Registra la condición en un log","Define una condición invariante para documentación"], correct:1, explanation:"assert se usa en tests y depuración: assert 0<=nota<=10, 'Nota inválida'. Se puede deshabilitar con python -O (optimized).", noShuffle:false },
  { concept_id:"py_u2_q22", unit:2, question:"¿Cómo se realizan múltiples asignaciones en una sola línea en Python?", options:["a = 1; b = 2, concepto diferente al que se describe en esta pregunta","a, b = 1, 2 (desempaquetado de tupla)","a = b = 1,2, concepto diferente al que se describe en esta pregunta","var a=1, b=2, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"a, b = 1, 2. Swap: a, b = b, a. Con rest: a, *b, c = [1,2,3,4,5] → a=1, b=[2,3,4], c=5.", noShuffle:false },
  { concept_id:"py_u2_q23", unit:2, question:"¿Qué es una comprensión de conjunto (set comprehension) en Python?", options:["No existen","Sintaxis compacta para crear sets: {expresion for elemento in iterable if condicion}","Una forma de crear conjuntos matemáticos","Un set con un único elemento"], correct:1, explanation:"{x%10 for x in range(100)} → dígitos únicos. El resultado es un set sin duplicados.", noShuffle:false },
  { concept_id:"py_u2_q24", unit:2, question:"¿Cuántas veces se ejecuta el bucle 'for i in range(3, 10, 2)'?", options:["7","3","4","6"], correct:2, explanation:"range(3,10,2): 3,5,7,9 → 4 iteraciones. El 10 no se incluye (stop es exclusivo). (10-3)//2+1=4 si calculamos a mano.", noShuffle:false },
  { concept_id:"py_u2_q25", unit:2, question:"¿Cómo se puede salir de bucles anidados en Python?", options:["double-break, concepto diferente al que se describe en esta pregunta","break solo sale del bucle más interno; para salir de ambos: usar una bandera booleana o poner el código en una función y usar return","nested-exit, concepto diferente al que se describe en esta pregunta","Python tiene una sentencia break-all, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Python no tiene break etiquetado (como Java). Opciones: función+return, bandera, itertools.product, o refactorizar.", noShuffle:false },
  { concept_id:"py_u2_q26", unit:2, question:"¿Qué hace map(función, iterable) en Python?", options:["Aplica la función a cada elemento del iterable y crea un mapa geográfico","Devuelve un iterador que aplica la función a cada elemento del iterable (lazy)","Crea un diccionario a partir del iterable","Filtra el iterable con la función"], correct:1, explanation:"map(str, [1,2,3]) → iterador de strings. list(map(lambda x:x**2, range(5))) → [0,1,4,9,16]. En Python 3, map es lazy.", noShuffle:false },
  { concept_id:"py_u2_q27", unit:2, question:"¿Qué hace filter(función, iterable) en Python?", options:["Filtra archivos del sistema de ficheros, concepto diferente al que se describe en esta pregunta","Devuelve un iterador con los elementos del iterable para los que la función retorna True","Transforma los elementos del iterable, concepto diferente al que se describe en esta pregunta","Crea un nuevo iterable con la función aplicada a cada elemento, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"filter(lambda x:x>0, [-1,2,-3,4]) → iterador de 2,4. list(filter(None, [0,'',1,'a'])) → [1,'a'] (elimina falsy).", noShuffle:false },
  { concept_id:"py_u2_q28", unit:2, question:"¿Qué hace reduce() en Python y en qué módulo está?", options:["Está en builtins directamente, concepto diferente al que se describe en esta pregunta","En functools.reduce: aplica una función acumulativa a los elementos del iterable para reducirlos a un único valor","Está en itertools, concepto diferente al que se describe en esta pregunta","En collections.reduce, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"from functools import reduce; reduce(lambda acc,x:acc+x, [1,2,3,4]) → 10. Python 3 lo movió a functools (no es builtin).", noShuffle:false },
  { concept_id:"py_u2_q29", unit:2, question:"¿Cuál es la ventaja de las expresiones generadoras sobre las comprensiones de listas?", options:["Las listas son siempre más rápidas, concepto diferente al que se describe en esta pregunta","Los generadores no almacenan todos los elementos en memoria a la vez (lazy evaluation), ideales para grandes datasets","Las listas tienen más métodos, concepto diferente al que se describe en esta pregunta","Los generadores pueden modificarse después de crearse, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"sum(x**2 for x in range(1000000)) usa O(1) memoria. [x**2 for x in range(1000000)] usa O(n) memoria.", noShuffle:false },
  { concept_id:"py_u2_q30", unit:2, question:"¿Cómo se puede iterar de forma inversa sobre una lista sin crearla al revés?", options:["for x in reversed(lista)","for x in lista.reversed()","for x in lista[::-1]","Ambas a y c son válidas"], correct:3, explanation:"reversed(lista) es un iterador inverso (no copia). lista[::-1] crea una nueva lista invertida (usa más memoria). Ambas son válidas.", noShuffle:false },
  { concept_id:"py_u2_q31", unit:2, question:"¿Qué módulo de Python proporciona herramientas avanzadas de iteración como chain, product, permutations?", options:["functools","itertools","collections","operator"], correct:1, explanation:"itertools: cycle, chain, product, permutations, combinations, groupby, islice... Para procesamiento eficiente de datos en grandes cantidades.", noShuffle:false },
  { concept_id:"py_u2_q32", unit:2, question:"¿Qué es el 'pattern matching' (match-case) de Python 3.10?", options:["Una forma de comparar strings con regex, concepto diferente al que se describe en esta pregunta","Una estructura de control que compara un valor con patrones estructurales (valores, tipos, secuencias, mapeos, clases)","Un sistema de templates, que aunque es una herramienta util, no corresponde a esta definicion","Una forma de comparar objetos, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"match punto: case Point(x=0,y=0): origen. case Point(x=0,y=y): eje Y. case _: otro. Mucho más potente que switch de otros lenguajes.", noShuffle:false },
  { concept_id:"py_u2_q33", unit:2, question:"¿Cuál es la diferencia entre list.sort() y sorted(list)?", options:["Son equivalentes, concepto diferente al que se describe en esta pregunta","list.sort() ordena in-place y devuelve None; sorted() no modifica y devuelve una nueva lista","sorted() es más rápido, concepto diferente al que se describe en esta pregunta","list.sort() admite clave; sorted() no, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"sort() modifica el original (in-place). sorted() es funcional: no modifica. Ambos aceptan key= y reverse=True.", noShuffle:false },
  { concept_id:"py_u2_q34", unit:2, question:"¿Qué hace la función min() con un argumento key?", options:["Devuelve el mínimo del parámetro key, concepto diferente al que se describe en esta pregunta","Usa la función key para calcular el valor de comparación: min(palabras","Filtra elementos menores a key, concepto diferente al que se describe en esta pregunta","Ordena usando key como criterio, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"min/max con key: min(['Python','C','Java'], key=len) → 'C'. También: min(estudiantes, key=lambda e:e.nota) → peor nota.", noShuffle:false },
  { concept_id:"py_u2_q35", unit:2, question:"¿Cómo se genera una lista de números pares del 0 al 20 con comprensión de lista?", options:["[n for n in range(20) if even(n)]","[n for n in range(0,21) if n%2==0]","list.range(0,20,2)","filter(even, range(21))"], correct:1, explanation:"[n for n in range(0,21) if n%2==0] → [0,2,4,...,20]. Alternativamente: list(range(0,21,2)) es más eficiente para secuencias simples.", noShuffle:false },
  { concept_id:"py_u2_q36", unit:2, question:"¿Qué hace itertools.chain(*iterables)?", options:["Crea una cadena de Promises, concepto diferente al que se describe en esta pregunta","Encadena múltiples iterables en uno solo sin crear una lista intermedia","Copia iterables en cadena, concepto diferente al que se describe en esta pregunta","Crea cadenas de texto de iterables, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"chain([1,2],[3,4],[5]) → iterador 1,2,3,4,5. Útil para unir iterables sin concatenar listas.", noShuffle:false },
  { concept_id:"py_u2_q37", unit:2, question:"¿Qué es la evaluación corto circuito (short-circuit) en Python?", options:["Un error de evaluación infinita, concepto diferente al que se describe en esta pregunta","and y or no evalúan el segundo operando si el resultado ya está determinado por el primero","Una optimización del intérprete para bucles, concepto diferente al que se describe en esta pregunta","Una forma de salir de funciones recursivas, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"False and función() → no llama a función(). True or función() → no llama. Útil para evitar errores: obj and obj.metodo().", noShuffle:false },
  { concept_id:"py_u2_q38", unit:2, question:"¿Cuántas iteraciones hace el bucle: 'for _ in range(5): pass'?", options:["0","1","5","indefinidas"], correct:2, explanation:"range(5) genera 0,1,2,3,4 → 5 iteraciones. El _ indica que no necesitamos el valor del contador.", noShuffle:false },
  { concept_id:"py_u2_q39", unit:2, question:"¿Cómo se puede hacer un bucle que itera solo N veces sin variable de contador?", options:["repeat(N):","for _ in range(N):","loop N times:","N.times { }"], correct:1, explanation:"for _ in range(N): es el idioma de Python para repetir N veces sin usar el índice. _ indica 'valor ignorado'.", noShuffle:false },
  { concept_id:"py_u2_q40", unit:2, question:"¿Qué diferencia hay entre 'not in' e 'is not' en Python?", options:["Son equivalentes, concepto diferente al que se describe en esta pregunta","not in: comprueba si un elemento NO está en una colección","not in es para listas; is not para objetos","is not es equivalente a !=, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"'x not in lista': pertenencia. 'x is not None': identidad. Usar 'is not None' para comprobar None, no '!= None'.", noShuffle:false },
  { concept_id:"py_u2_q41", unit:2, question:"¿Qué hace next() aplicado a un generador o iterador?", options:["Salta al siguiente elemento sin devolverlo, concepto diferente al que se describe en esta pregunta","Devuelve el siguiente elemento del iterador; lanza StopIteration si no hay más","Crea el siguiente elemento generador, concepto diferente al que se describe en esta pregunta","Añade un elemento al generador, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"next(gen) → siguiente valor. next(gen, default) → default en lugar de StopIteration. Los bucles for llaman a next() automáticamente.", noShuffle:false },
  { concept_id:"py_u2_q42", unit:2, question:"¿Qué devuelve la expresión '[x for x in range(5)][::-1]'?", options:["[0,1,2,3,4]","[4,3,2,1,0]","[5,4,3,2,1]","Error de sintaxis"], correct:1, explanation:"[x for x in range(5)] → [0,1,2,3,4]. [::-1] invierte: [4,3,2,1,0]. Equivalente y más directo: list(range(4,-1,-1)).", noShuffle:false },

  // ════════════════════════════════════════════════════════════════
  //  UNIDAD 3 — Funciones en Python
  // ════════════════════════════════════════════════════════════════
  { concept_id:"py_u3_q1", unit:3, question:"¿Cuál es la sintaxis correcta para definir una función en Python?", options:["function nombre(params):","def nombre(params):","fn nombre(params):","function: nombre(params)"], correct:1, explanation:"def nombre(parametros): → cuerpo indentado. Toda la función es el cuerpo indentado. No requiere llaves.", noShuffle:false },
  { concept_id:"py_u3_q2", unit:3, question:"¿Cuándo devuelve None una función Python automáticamente?", options:["Cuando tiene un error, concepto diferente al que se describe en esta pregunta","Cuando no tiene instrucción 'return' o tiene 'return' sin valor","Siempre al final, concepto diferente al que se describe en esta pregunta","Cuando el cuerpo está vacío, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Las funciones sin return (o con return vacío) devuelven None implícitamente. Las funciones void de C equivalen a esto.", noShuffle:false },
  { concept_id:"py_u3_q3", unit:3, question:"¿Qué son los parámetros con valor por defecto en Python?", options:["Parámetros que siempre tienen el mismo valor, concepto diferente al que se describe en esta pregunta","Parámetros opcionales que toman un valor predefinido si no se pasa argumento: def fn(x, y=0)","Parámetros que no pueden ser None, concepto diferente al que se describe en esta pregunta","Parámetros que se generan automáticamente, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"def saludar(nombre, saludo='Hola'): saludar('Ana') → 'Hola Ana'. Los parámetros con default van DESPUÉS de los obligatorios.", noShuffle:false },
  { concept_id:"py_u3_q4", unit:3, question:"¿Qué hace '*args' en la definición de una función?", options:["Define un argumento de tipo array, concepto diferente al que se describe en esta pregunta","Captura un número variable de argumentos posicionales como tupla","Hace que todos los argumentos sean opcionales, concepto diferente al que se describe en esta pregunta","Define el único argumento de la función, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"def fn(*args): → args es una tupla con todos los posicionales. fn(1,2,3) → args=(1,2,3). Convención: args (pero puede llamarse cualquier cosa).", noShuffle:false },
  { concept_id:"py_u3_q5", unit:3, question:"¿Qué hace '**kwargs' en la definición de una función?", options:["Eleva los argumentos a potencias","Captura un número variable de argumentos por nombre (keyword) como diccionario","Define argumentos de tipo keyword-only","Desempaqueta los argumentos automáticamente"], correct:1, explanation:"def fn(**kwargs): fn(nombre='Ana', edad=25) → kwargs={'nombre':'Ana', 'edad':25}. Usado en funciones muy flexibles.", noShuffle:false },
  { concept_id:"py_u3_q6", unit:3, question:"¿Qué es una función lambda en Python?", options:["Una función de AWS Lambda, concepto diferente al que se describe en esta pregunta","Una función anónima de una sola expresión: lambda params: expresión","Una función especial para procesamiento paralelo","Una función que solo acepta números, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"lambda x: x**2. Equivale a def f(x): return x**2 pero sin nombre. Usada como argumento: sorted(lista, key=lambda x:x['nombre']).", noShuffle:false },
  { concept_id:"py_u3_q7", unit:3, question:"¿Qué es un decorador (@) en Python?", options:["Un comentario especial, concepto diferente al que se describe en esta pregunta","Una función que envuelve otra función para añadir comportamiento sin modificar la función original","Una forma de herencia, concepto diferente al que se describe en esta pregunta","Un tipo de importación, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"@decorador sobre una función. Equivale a: funcion = decorador(funcion). Usado en frameworks (Flask @app.route, Django @login_required).", noShuffle:false },
  { concept_id:"py_u3_q8", unit:3, question:"¿Qué es el scope (ámbito) en Python?", options:["El tamaño de una función, concepto que se aplica en un contexto distinto","La región del código donde una variable es accesible (LEGB: Local","La lista de parámetros de una función, concepto que se aplica en un contexto distinto","El número de líneas de una función, concepto que se aplica en un contexto distinto"], correct:1, explanation:"LEGB: primero Local → luego Enclosing (closures) → luego Global → por último Built-in. Python busca en este orden.", noShuffle:false },
  { concept_id:"py_u3_q9", unit:3, question:"¿Para qué sirve la declaración 'global' dentro de una función?", options:["Hace la función accesible globalmente, concepto diferente al que se describe en esta pregunta","Declara que la variable con ese nombre es la variable global (no crea una nueva local)","Define variables de sistema, concepto diferente al que se describe en esta pregunta","Hace la función ejecutable desde cualquier módulo, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"sin global: variable = valor crea una variable local. Con global variable: modifica la variable del módulo global. Usar con precaución.", noShuffle:false },
  { concept_id:"py_u3_q10", unit:3, question:"¿Qué es un closure (clausura) en Python?", options:["El cierre de un archivo, concepto que se aplica en un contexto distinto","Una función que recuerda los valores de las variables de su ámbito exterior incluso después de que ese ámbito termine","Una función sin argumentos, concepto diferente al que se describe en esta pregunta","Un tipo de decorador, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"def contador(): n=0; def inc(): nonlocal n; n+=1; return n; return inc. La función inc 'recuerda' n aunque contador ya haya terminado.", noShuffle:false },
  { concept_id:"py_u3_q11", unit:3, question:"¿Para qué sirve 'nonlocal' dentro de una función anidada?", options:["Hace la variable accesible globalmente, concepto diferente al que se describe en esta pregunta","Declara que la variable pertenece al scope de la función envolvente (ni local ni global)","Evita que la variable se elimine al salir de la función, concepto diferente al que se describe en esta pregunta","Crea una copia de la variable exterior, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"nonlocal x: modifica la x de la función padre (closure). Sin nonlocal, asignar a x crearía una nueva variable local.", noShuffle:false },
  { concept_id:"py_u3_q12", unit:3, question:"¿Qué es el docstring de una función Python?", options:["Un comentario con ##, concepto diferente al que se describe en esta pregunta","La primera cadena de texto dentro de una función/clase/módulo que documenta su propósito","Un tipo especial de return, concepto diferente al que se describe en esta pregunta","Una cadena de formato para los parámetros, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"def fn(): \"\"\"Descripción de la función.\"\"\". Accesible con fn.__doc__ o help(fn). Las herramientas generan documentación de los docstrings.", noShuffle:false },
  { concept_id:"py_u3_q13", unit:3, question:"¿Qué son las anotaciones de tipo (type hints) en Python?", options:["Comentarios especiales de tipo, concepto diferente al que se describe en esta pregunta","Información opcional de tipo en la firma de funciones: def fn(x: int","Una forma de forzar el tipo de los parámetros, concepto diferente al que se describe en esta pregunta","Solo para IDEs, no afectan al intérprete, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Type hints (PEP 484): x: int, lista: List[str], -> dict. No se fuerzan en tiempo de ejecución (por defecto), pero las usan mypy, IDEs y frameworks como FastAPI.", noShuffle:false },
  { concept_id:"py_u3_q14", unit:3, question:"¿Cómo se puede desempaquetar una lista al llamar a una función?", options:["fn(lista)","fn(*lista)","fn(**lista)","fn(unpack(lista))"], correct:1, explanation:"def fn(a,b,c): ...; lista=[1,2,3]; fn(*lista) → fn(1,2,3). Para kwargs: fn(**{'x':1,'y':2}). Muy útil con zip, range, etc.", noShuffle:false },
  { concept_id:"py_u3_q15", unit:3, question:"¿Qué es la recursión y cuál es la profundidad de recursión por defecto en Python?", options:["Bucles anidados; sin límite, concepto diferente al que se describe en esta pregunta","Una función que se llama a sí misma; el límite por defecto es 1000 (configurable con sys.setrecursionlimit())","Solo para funciones matemáticas; 100 niveles, concepto diferente al que se describe en esta pregunta","Para árboles de datos; 500 niveles, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"La pila de Python tiene límite (~1000). Para recursión profunda: convertir a iteración o usar trampolín. sys.setrecursionlimit(10000).", noShuffle:false },
  { concept_id:"py_u3_q16", unit:3, question:"¿Qué hace functools.lru_cache en Python?", options:["Ejecuta la función en un caché LRU de hardware, concepto diferente al que se describe en esta pregunta","Decorador que memoriza (cachea) los resultados de las llamadas a la función según sus argumentos","Limita el número de llamadas a una función, concepto diferente al que se describe en esta pregunta","Limpia la caché de la función, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"@lru_cache(maxsize=128): fib(n) memoizado automáticamente. Si n ha sido calculado, devuelve el resultado cacheado sin recalcular.", noShuffle:false },
  { concept_id:"py_u3_q17", unit:3, question:"¿Cómo se pasan argumentos solo por nombre (keyword-only) en Python?", options:["def fn(*,x,y): → x e y solo se pueden pasar como keyword","def fn(x=None,y=None): x e y son keyword-only","def fn(keyword x,y): → definición especial","No es posible en Python"], correct:0, explanation:"def fn(a, *, b, c): → b y c son keyword-only (deben pasarse como fn(1, b=2, c=3)). Los parámetros tras * no pueden pasarse por posición.", noShuffle:false },
  { concept_id:"py_u3_q18", unit:3, question:"¿Qué función de Python aplica otra función a todos los elementos de un iterable?", options:["apply(), concepto diferente al que se describe en esta pregunta","each(), concepto diferente al que se describe en esta pregunta","map(función, iterable)","forEach(), concepto diferente al que se describe en esta pregunta"], correct:2, explanation:"map(str, [1,2,3]) → iterador de strings. list(map(lambda x:x*2, range(5))) → [0,2,4,6,8]. En Python 3, map es lazy (generador).", noShuffle:false },
  { concept_id:"py_u3_q19", unit:3, question:"¿Cuál es la diferencia entre argumentos posicionales y por nombre (keyword) en Python?", options:["Son equivalentes siempre, concepto diferente al que se describe en esta pregunta","Posicionales: se pasan por orden. Keyword: se pasan por nombre (fn(x=1,y=2)) y pueden estar en cualquier orden","Los posicionales son más rápidos, concepto diferente al que se describe en esta pregunta","Los keyword no pueden tener valores por defecto, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"fn(1, 2): posicionales. fn(y=2, x=1): keyword (el orden no importa). fn(1, y=2): mixto (posicionales antes de keyword).", noShuffle:false },
  { concept_id:"py_u3_q20", unit:3, question:"¿Cómo se implementa un decorador básico en Python?", options:["def decorador(func): return lambda *a,**k: func(*a,**k)","class Decorador(func): pass","@func → def decorador():","No se pueden implementar, solo usar los predefinidos"], correct:0, explanation:"def log(func): def wrapper(*a,**k): print('Llamando'); result=func(*a,**k); print('Hecho'); return result; return wrapper; @log def fn(): ...", noShuffle:false },
  { concept_id:"py_u3_q21", unit:3, question:"¿Qué hace functools.partial() en Python?", options:["Devuelve parte del resultado de una función, concepto diferente al que se describe en esta pregunta","Crea una nueva función con algunos argumentos ya fijados (aplicación parcial)","Ejecuta una función de forma parcial (hasta la mitad), concepto diferente al que se describe en esta pregunta","Crea una versión asíncrona de la función, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"from functools import partial; doble = partial(pow, exp=2); doble(base=3)→9. Útil para adaptar funciones a interfaces que requieren menos argumentos.", noShuffle:false },
  { concept_id:"py_u3_q22", unit:3, question:"¿Cuándo usar una función generadora (con yield) en lugar de devolver una lista?", options:["Cuando la lista tiene menos de 100 elementos, concepto diferente al que se describe en esta pregunta","Cuando la secuencia puede ser muy grande o infinita y no queremos cargarla toda en memoria","Las funciones generadoras son siempre más rápidas, concepto diferente al que se describe en esta pregunta","Solo para secuencias numéricas, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"def contar(n): i=0; while i<n: yield i; i+=1. Produce un elemento a la vez. Ficheros grandes, streams de datos, secuencias infinitas.", noShuffle:false },
  { concept_id:"py_u3_q23", unit:3, question:"¿Qué es el unpacking de argumentos con ** para diccionarios?", options:["Elevar al cuadrado los valores del diccionario","Pasar las claves y valores del diccionario como argumentos keyword a una función: fn(**{'x':1,'y':2}) → fn(x=1,y=2)","Crear una copia del diccionario","Imprimir el diccionario en formato especial"], correct:1, explanation:"config={'debug':True,'port':8080}; iniciar(**config) equivale a iniciar(debug=True, port=8080). Muy usado en frameworks.", noShuffle:false },
  { concept_id:"py_u3_q24", unit:3, question:"¿Qué hace el decorador @staticmethod en Python?", options:["Hace la función inmutable, concepto diferente al que se describe en esta pregunta","Define un método que no recibe ni self ni cls, pertenece a la clase pero actúa como una función independiente","Cachea el resultado del método, concepto diferente al que se describe en esta pregunta","Hace el método accesible solo desde fuera de la clase, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"@staticmethod: útil para funciones auxiliares que lógicamente pertenecen a la clase pero no necesitan acceder a su estado.", noShuffle:false },
  { concept_id:"py_u3_q25", unit:3, question:"¿Qué diferencia hay entre @classmethod y @staticmethod en Python?", options:["Son equivalentes, concepto diferente al que se describe en esta pregunta","classmethod recibe la clase (cls) como primer parámetro","staticmethod recibe la clase; classmethod no recibe nada","classmethod solo funciona en clases abstractas"], correct:1, explanation:"@classmethod def crear(cls, ...): → útil para constructores alternativos. @staticmethod def utilidad(): → función sin acceso a la clase o instancia.", noShuffle:false },
  { concept_id:"py_u3_q26", unit:3, question:"¿Qué es la memoización y cómo se implementa manualmente en Python?", options:["Guardar funciones en disco","Cachear resultados de llamadas previas en un diccionario para evitar recálculos","Un tipo de recursión", "La documentación automática de funciones"], correct:1, explanation:"cache={}; def fib(n): if n in cache: return cache[n]; cache[n]=fib(n-1)+fib(n-2); return cache[n]. O usar @lru_cache.", noShuffle:false },
  { concept_id:"py_u3_q27", unit:3, question:"¿Cuál es la forma correcta de devolver múltiples valores de una función en Python?", options:["return a, b (devuelve una tupla implícitamente)","return [a, b]","return a; return b","No es posible devolver múltiples valores"], correct:0, explanation:"return a, b devuelve la tupla (a,b). Se puede desempaquetar: x, y = fn(). Técnicamente es una tupla, no múltiples valores.", noShuffle:false },
  { concept_id:"py_u3_q28", unit:3, question:"¿Qué es el operador * al hacer slicing extendido de listas?", options:["Hace el slicing más rápido","Captura el 'resto' en el desempaquetado: a, *b, c = [1,2,3,4,5] → a=1, b=[2,3,4], c=5","Repite el slice el número de veces indicado","Desempaqueta el resultado como argumentos"], correct:1, explanation:"Desempaquetado extendido (Python 3): a, *b = [1,2,3,4] → a=1, b=[2,3,4]. first, *_, last = [1,2,3,4] → first=1, last=4.", noShuffle:false },
  { concept_id:"py_u3_q29", unit:3, question:"¿Qué hace help(función) en Python?", options:["Busca la función en internet","Muestra el docstring y la firma de la función","Abre la documentación oficial","Muestra el código fuente de la función"], correct:1, explanation:"help(len) → muestra docstring. fn.__doc__ → solo el docstring. inspect.signature(fn) → la firma (parámetros y tipos).", noShuffle:false },
  { concept_id:"py_u3_q30", unit:3, question:"¿Cuál es la diferencia entre throw y raise en Python?", options:["Son lo mismo, concepto diferente al que se describe en esta pregunta","Python usa 'raise' para lanzar excepciones; 'throw' es de Java/JavaScript","raise es para errores; throw para advertencias, concepto diferente al que se describe en esta pregunta","throw es más moderno que raise, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"raise ValueError('Mensaje'). raise sin argumentos re-lanza la excepción actual (en el except). No existe throw en Python.", noShuffle:false },
  { concept_id:"py_u3_q31", unit:3, question:"¿Para qué sirve functools.wraps en decoradores?", options:["Para envolver objetos como los decoradores de JavaScript, concepto diferente al que se describe en esta pregunta","Para preservar el nombre, docstring y firma de la función original cuando se crea un wrapper","Para hacer el decorador reutilizable, concepto diferente al que se describe en esta pregunta","Para combinar múltiples decoradores, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Sin @wraps(fn): la función decorada pierde su __name__ y __doc__. Con @wraps(fn): los conserva. Importante para debugging y documentación.", noShuffle:false },
  { concept_id:"py_u3_q32", unit:3, question:"¿Cómo se puede saber si un objeto es 'callable' (función, método, clase...) en Python?", options:["obj.isFunction()","callable(obj)","type(obj) == function","hasattr(obj, '__call__')"], correct:1, explanation:"callable(obj) devuelve True si el objeto tiene __call__. Las funciones, métodos, clases y cualquier objeto con __call__ son callable.", noShuffle:false },
  { concept_id:"py_u3_q33", unit:3, question:"¿Qué devuelve una función generadora cuando se llama con ()?", options:["El primer valor generado, concepto diferente al que se describe en esta pregunta","Un objeto generador (iterator), no el primer valor","None hasta que se llame next(), concepto diferente al que se describe en esta pregunta","Una lista con todos los valores, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Llamar a una función con yield devuelve un generador, no ejecuta el cuerpo. El cuerpo se ejecuta al consumir el generador con next() o for.", noShuffle:false },
  { concept_id:"py_u3_q34", unit:3, question:"¿Cuándo se usa @property en Python?", options:["Para hacer la propiedad pública, concepto diferente al que se describe en esta pregunta","Para crear métodos accesibles como atributos: obj.nombre (no obj.nombre())","Para definir propiedades de clase estáticas, concepto diferente al que se describe en esta pregunta","Para crear constantes de clase, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"@property def area(self): return self._ancho * self._alto. obj.area (sin paréntesis). @area.setter y @area.deleter para el setter y deleter.", noShuffle:false },
  { concept_id:"py_u3_q35", unit:3, question:"¿Cómo se implementa una función que acepta cualquier número y tipo de argumentos?", options:["def fn(anything):","def fn(*args, **kwargs):","def fn(...):","def fn(params=None):"], correct:1, explanation:"def fn(*args, **kwargs): → args es tupla de posicionales, kwargs es dict de keyword. Patrón común en wrappers y decoradores.", noShuffle:false },
  { concept_id:"py_u3_q36", unit:3, question:"¿Qué es la programación funcional en Python y cómo se diferencia de la OOP?", options:["Son lo mismo, concepto diferente al que se describe en esta pregunta","FP usa funciones puras, evita estado mutable y efectos secundarios","FP es más antigua que OOP, concepto diferente al que se describe en esta pregunta","OOP es más lenta que FP en Python, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Python soporta ambos paradigmas. FP: map/filter/reduce/lambdas, inmutabilidad, sin side effects. OOP: clases, herencia, polimorfismo.", noShuffle:false },
  { concept_id:"py_u3_q37", unit:3, question:"¿Qué hace operator.itemgetter(0) en Python?", options:["Obtiene el elemento en la posición 0 de todos los elementos de una lista","Crea una función que extrae el elemento en la posición/clave dada de un objeto","Borra el primer elemento de una lista","Comprueba si el índice 0 existe en un iterable"], correct:1, explanation:"from operator import itemgetter; sorted(pares, key=itemgetter(1)) → ordena por el segundo elemento. Más rápido que lambda para casos simples.", noShuffle:false },
  { concept_id:"py_u3_q38", unit:3, question:"¿Cuál es el patrón para medir el tiempo de ejecución de una función?", options:["import time; t0=time.time(); fn(); print(time.time()-t0)","Usar el decorador @time de Python, concepto diferente al que se describe en esta pregunta","fn.timer(), concepto diferente al que se describe en esta pregunta","performance.now() como en JS, concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"import time; inicio=time.perf_counter(); resultado=fn(); print(time.perf_counter()-inicio,'s'). perf_counter es de mayor precisión que time().", noShuffle:false },
  { concept_id:"py_u3_q39", unit:3, question:"¿Qué hace el módulo 'inspect' de Python?", options:["Inspecciona conexiones de red, concepto diferente al que se describe en esta pregunta","Permite examinar objetos vivos: obtener código fuente, firma de funciones","Inspecciona la sintaxis del código, concepto diferente al que se describe en esta pregunta","Analiza la cobertura de tests, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"inspect.signature(fn), inspect.getsource(fn), inspect.getmembers(obj), inspect.isfunction(obj). Muy útil para frameworks y herramientas de debugging.", noShuffle:false },
  { concept_id:"py_u3_q40", unit:3, question:"¿Qué hace 'yield from' en una función generadora?", options:["Sale de todos los generadores anidados, concepto diferente al que se describe en esta pregunta","Delega la producción de valores a otro generador/iterable (equivalente a for x in iterable: yield x)","Define un subgenerador, concepto diferente al que se describe en esta pregunta","Combina dos generadores en uno, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"def gen(): yield from range(5) → delega a range(5). Más limpio y eficiente que el bucle. También propaga .send() y .throw().", noShuffle:false },
  { concept_id:"py_u3_q41", unit:3, question:"¿Para qué sirve el módulo contextlib de Python?", options:["Para gestionar el contexto de aplicaciones web, concepto diferente al que se describe en esta pregunta","Para crear gestores de contexto (with statement) fácilmente: @contextmanager con yield","Para contextos de ejecución seguros, concepto diferente al que se describe en esta pregunta","Para gestionar variables de contexto en async, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"@contextmanager def abrir_db(): conn=conectar(); try: yield conn; finally: conn.close(). with abrir_db() as db: usar(db).", noShuffle:false },
  { concept_id:"py_u3_q42", unit:3, question:"¿Qué diferencia hay entre una excepción y un error en Python?", options:["Son lo mismo: todas las excepciones son errores, concepto diferente al que se describe en esta pregunta","Las excepciones son el mecanismo de manejo; los errores son subclases de Exception (ValueError, TypeError, etc.)","Los errores no se pueden capturar, concepto diferente al que se describe en esta pregunta","Las excepciones son solo para IO, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"BaseException → Exception → diversas subclases (ValueError, TypeError, IOError...). Todas son 'excepciones'. Los built-in errors son subclases de Exception.", noShuffle:false },

  // ════════════════════════════════════════════════════════════════
  //  UNIDAD 4 — Estructuras de datos
  // ════════════════════════════════════════════════════════════════
  { concept_id:"py_u4_q1", unit:4, question:"¿Cuál es la diferencia entre lista y tupla en Python?", options:["Solo el nombre cambia, concepto diferente al que se describe en esta pregunta","Las listas son mutables (se pueden modificar); las tuplas son inmutables (no se pueden cambiar tras su creación)","Las tuplas son más lentas, concepto diferente al que se describe en esta pregunta","Las listas no pueden tener elementos duplicados, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Lista: [1,2,3] → mutable. Tupla: (1,2,3) → inmutable. Las tuplas son más rápidas y se pueden usar como claves de diccionario.", noShuffle:false },
  { concept_id:"py_u4_q2", unit:4, question:"¿Cómo se añade un elemento al final de una lista?", options:["lista.add(elemento)","lista.append(elemento)","lista.push(elemento)","lista.insert_end(elemento)"], correct:1, explanation:"append(x): añade al final O(1). extend([x,y]): añade múltiples. insert(i,x): inserta en posición i O(n). += [x] también funciona.", noShuffle:false },
  { concept_id:"py_u4_q3", unit:4, question:"¿Qué es un diccionario en Python y cuál es su principal característica?", options:["Una lista de palabras reservadas, concepto diferente al que se describe en esta pregunta","Una colección de pares clave-valor donde las claves deben ser inmutables y son únicas","Una lista ordenada de elementos, concepto diferente al que se describe en esta pregunta","Una función que traduce strings, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"dict: acceso O(1) por clave (hash table). Desde Python 3.7, mantiene el orden de inserción. Claves: strings, números, tuplas (inmutables).", noShuffle:false },
  { concept_id:"py_u4_q4", unit:4, question:"¿Cómo se accede a una clave de diccionario sin lanzar excepción si no existe?", options:["dict[clave] (silencia la excepción)","dict.get(clave, valorPorDefecto)","dict.find(clave)","dict.safe_get(clave)"], correct:1, explanation:"dict.get('clave', 0): devuelve 0 si no existe la clave (sin KeyError). dict['clave'] lanza KeyError si no existe.", noShuffle:false },
  { concept_id:"py_u4_q5", unit:4, question:"¿Qué es un set en Python?", options:["Una lista de valores únicos ordenada","Una colección no ordenada de valores únicos sin duplicados, con operaciones de conjuntos","Un tipo especial de diccionario","Un array de tipo fijo"], correct:1, explanation:"set: {1,2,3}. Operaciones: | (unión), & (intersección), - (diferencia), ^ (diferencia simétrica). No tiene índices ni duplicados.", noShuffle:false },
  { concept_id:"py_u4_q6", unit:4, question:"¿Cómo se crea un conjunto vacío en Python?", options:["{}","set()","[]","()"], correct:1, explanation:"{} crea un diccionario vacío, NO un set. El único modo de crear un set vacío es set(). set([1,2,2,3]) → {1,2,3}.", noShuffle:false },
  { concept_id:"py_u4_q7", unit:4, question:"¿Qué hace lista[::2] en Python?", options:["Los últimos 2 elementos, concepto diferente al que se describe en esta pregunta","Cada 2 elementos: índices 0, 2, 4, 6... (paso 2)","Los 2 primeros elementos, concepto diferente al que se describe en esta pregunta","El elemento en la posición 2, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Slicing: lista[inicio:fin:paso]. [::2] → de inicio a fin con paso 2. [::-1] → invertida. [1:5] → elementos 1,2,3,4.", noShuffle:false },
  { concept_id:"py_u4_q8", unit:4, question:"¿Qué hace dict.setdefault(clave, valor)?", options:["Establece siempre el valor dado, concepto diferente al que se describe en esta pregunta","Si la clave no existe, la añade con el valor dado y la devuelve","Es equivalente a dict[clave] = valor","Borra el valor si ya existe"], correct:1, explanation:"setdefault: patrón común para contar: d.setdefault(k, 0); d[k]+=1. O para listas: d.setdefault(k,[]).append(v).", noShuffle:false },
  { concept_id:"py_u4_q9", unit:4, question:"¿Cuál es la complejidad temporal del acceso a un elemento en una lista por índice?", options:["O(n)","O(log n)","O(1)","O(n²)"], correct:2, explanation:"El acceso por índice en listas Python (arrays dinámicos) es O(1). La búsqueda de un valor es O(n). El acceso a dict y set también es O(1) amortizado.", noShuffle:false },
  { concept_id:"py_u4_q10", unit:4, question:"¿Cómo se fusionan dos diccionarios en Python?", options:["dict1.merge(dict2)","dict1.update(dict2) (modifica dict1) o {**dict1, **dict2} (nuevo dict) o dict1 | dict2 (Python 3.9+)","dict1 + dict2","dict.combine(dict1, dict2)"], correct:1, explanation:"update(): modifica. {**d1,**d2}: crea nuevo. d1|d2 (Python 3.9+): crea nuevo. En colisiones, el último sobrescribe.", noShuffle:false },
  { concept_id:"py_u4_q11", unit:4, question:"¿Para qué se usa collections.defaultdict?", options:["Para diccionarios ordenados, concepto diferente al que se describe en esta pregunta","Un diccionario que retorna un valor por defecto para claves inexistentes (no lanza KeyError)","Para diccionarios de solo lectura, concepto diferente al que se describe en esta pregunta","Para diccionarios con claves de tipo predefinido, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"from collections import defaultdict; d=defaultdict(int); d['a']+=1 (sin inicializar). defaultdict(list) para agrupar: d[k].append(v).", noShuffle:false },
  { concept_id:"py_u4_q12", unit:4, question:"¿Qué devuelve dict.pop(clave, default)?", options:["Elimina y devuelve el valor de la clave; si no existe devuelve default (o KeyError sin default)","Devuelve sin eliminar, concepto diferente al que se describe en esta pregunta","Agrega la clave con el valor default si no existe, concepto diferente al que se describe en esta pregunta","Elimina el primer elemento del diccionario, concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"pop() elimina y devuelve. popitem() elimina y devuelve el último par (LIFO, Python 3.7+). clear() vacía todo el dict.", noShuffle:false },
  { concept_id:"py_u4_q13", unit:4, question:"¿Cuál es la diferencia entre lista.remove() y lista.pop()?", options:["Son idénticos, concepto diferente al que se describe en esta pregunta","remove(valor) elimina la primera ocurrencia del valor; pop(índice) elimina y devuelve el elemento en esa posición","remove() devuelve el elemento; pop() no, concepto diferente al que se describe en esta pregunta","pop() elimina por valor; remove() por índice, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"remove(x): busca y elimina primera x. ValueError si no existe. pop(): elimina y devuelve por índice. pop() sin argumento → último elemento.", noShuffle:false },
  { concept_id:"py_u4_q14", unit:4, question:"¿Qué es collections.namedtuple?", options:["Una tupla con nombre personalizado, concepto diferente al que se describe en esta pregunta","Una subclase de tupla cuyos elementos tienen nombre: Point = namedtuple('Point','x y'); p=Point(1,2); p.x→1","Un diccionario con nombres cortos, concepto diferente al que se describe en esta pregunta","Una lista con nombres de columna, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"namedtuple es inmutable como tupla pero con acceso por nombre. Buena alternativa a clases simples de datos.", noShuffle:false },
  { concept_id:"py_u4_q15", unit:4, question:"¿Para qué sirve collections.Counter?", options:["Un contador de bucles","Un diccionario especializado para contar frecuencias de elementos de un iterable","Un timer de ejecución","Un contador de errores"], correct:1, explanation:"Counter('banana') → {'a':3,'b':1,'n':2}. most_common(n) → top N más frecuentes. Soporta operaciones: c1+c2, c1-c2.", noShuffle:false },
  { concept_id:"py_u4_q16", unit:4, question:"¿Cómo se puede ordenar una lista de diccionarios por un campo específico?", options:["sorted(lista_dicts)","sorted(lista_dicts, key=lambda d:d['campo'])","lista_dicts.sort(by='campo')","sorted(lista_dicts, field='campo')"], correct:1, explanation:"sorted(estudiantes, key=lambda e:e['nota'], reverse=True) → ordenados por nota descendente. O: sorted(estudiantes, key=itemgetter('nota')).", noShuffle:false },
  { concept_id:"py_u4_q17", unit:4, question:"¿Qué hace el método dict.update() cuando hay claves duplicadas?", options:["Lanza KeyError","El diccionario fuente sobreescribe los valores del diccionario destino","Mantiene ambos valores en una lista","No actualiza las claves duplicadas"], correct:1, explanation:"Las claves del argumento sobreescriben. d1={'a':1}; d1.update({'a':2,'b':3}) → {'a':2,'b':3}.", noShuffle:false },
  { concept_id:"py_u4_q18", unit:4, question:"¿Cuál es la diferencia entre frozenset y set?", options:["frozenset es más rápido","frozenset es inmutable (no se puede modificar) y puede usarse como clave de diccionario o elemento de otro set","set es inmutable; frozenset es mutable","No hay diferencia práctica"], correct:1, explanation:"frozenset({1,2,3}): inmutable. set: mutable (add, remove, discard). frozenset como clave de dict: frozenset es hashable.", noShuffle:false },
  { concept_id:"py_u4_q19", unit:4, question:"¿Qué hace heapq en Python?", options:["Ordena listas como un heap, concepto diferente al que se describe en esta pregunta","Implementa una cola de prioridad (min-heap) sobre listas Python: heappush","Gestiona la memoria heap del intérprete, concepto diferente al que se describe en esta pregunta","Crea árboles binarios de búsqueda, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"import heapq; h=[]; heapq.heappush(h,3); heapq.heappush(h,1); heapq.heappop(h)→1 (el menor). nlargest(3,datos)→3 mayores.", noShuffle:false },
  { concept_id:"py_u4_q20", unit:4, question:"¿Qué es una deque (double-ended queue) de collections?", options:["Una lista de dos elementos, concepto diferente al que se describe en esta pregunta","Una cola de doble extremo eficiente para añadir/eliminar de ambos lados en O(1)","Un diccionario con dos claves por valor, concepto diferente al que se describe en esta pregunta","Una tupla con dos elementos, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"from collections import deque; d=deque([1,2,3]); d.appendleft(0); d.popleft(). Para implementar pilas y colas. Más eficiente que listas para inserciones al inicio.", noShuffle:false },
  { concept_id:"py_u4_q21", unit:4, question:"¿Cómo se comprueba si una clave existe en un diccionario?", options:["dict.hasKey('clave')","'clave' in dict","dict.contains('clave')","dict['clave'] != None"], correct:1, explanation:"'clave' in dict es la forma idiomática y eficiente (O(1)). dict.get('clave') es alternativa. dict['clave'] lanza KeyError si no existe.", noShuffle:false },
  { concept_id:"py_u4_q22", unit:4, question:"¿Cuál es la complejidad de añadir un elemento a un set en Python?", options:["O(n), concepto diferente al que se describe en esta pregunta","O(log n), concepto diferente al que se describe en esta pregunta","O(1) amortizado","O(n²), concepto diferente al que se describe en esta pregunta"], correct:2, explanation:"Los sets usan tablas hash. Operaciones básicas (add, remove, in): O(1) amortizado. Unión/intersección: O(min(len(s1),len(s2))).", noShuffle:false },
  { concept_id:"py_u4_q23", unit:4, question:"¿Qué hace lista.extend() versus lista.append() con otra lista?", options:["Son idénticos","extend([a,b,c]) añade cada elemento individualmente; append([a,b,c]) añade la lista como un único elemento anidado","append es más rápido que extend","extend solo funciona con tuplas"], correct:1, explanation:"lista.append([1,2]) → [..., [1,2]] (elemento=lista). lista.extend([1,2]) → [..., 1, 2] (añade cada uno). extend=+= en funcionalidad.", noShuffle:false },
  { concept_id:"py_u4_q24", unit:4, question:"¿Cómo se crea una copia profunda (deep copy) de una lista anidada en Python?", options:["lista.copy() o lista[:]","import copy; copy.deepcopy(lista)","list(lista)","lista.deepcopy()"], correct:1, explanation:"Shallow copy: lista[:] o list(lista) → copia el nivel superior pero los subelementos comparten referencia. deepcopy: copia recursivamente todo.", noShuffle:false },
  { concept_id:"py_u4_q25", unit:4, question:"¿Qué son las vistas de diccionario (dict.keys(), dict.values(), dict.items())?", options:["Copias estáticas de las claves/valores","Objetos dinámicos que reflejan los cambios del diccionario en tiempo real (vistas live)","Tuplas inmutables con las claves/valores","Generadores que producen claves/valores bajo demanda"], correct:1, explanation:"d={a:1}; k=d.keys(); d['b']=2; 'b' in k → True. Las vistas reflejan cambios del dict. Convertir a list() si necesitas snapshot.", noShuffle:false },
  { concept_id:"py_u4_q26", unit:4, question:"¿Cómo se elimina un elemento de un set sin lanzar error si no existe?", options:["set.remove(x) (no lanza error), concepto diferente al que se describe en esta pregunta","set.discard(x) (no lanza error si no existe)","set.delete(x), concepto diferente al que se describe en esta pregunta","set.pop(x), concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"discard(x): elimina si existe, no hace nada si no. remove(x): lanza KeyError si no existe. pop(): elimina y devuelve un elemento arbitrario.", noShuffle:false },
  { concept_id:"py_u4_q27", unit:4, question:"¿Qué es el slicing negativo en listas Python?", options:["Un error de sintaxis","Acceso desde el final: lista[-1]=último, lista[-2]=penúltimo, lista[-3:]=últimos 3 elementos","Un bucle que resta del índice","Solo funciona con tuplas"], correct:1, explanation:"lista[-1]: último. lista[-2:]: últimos 2. lista[:-1]: todos menos el último. lista[::-1]: invertida.", noShuffle:false },
  { concept_id:"py_u4_q28", unit:4, question:"¿Para qué se usa array module versus lista en Python?", options:["array es más fácil de usar, concepto diferente al que se describe en esta pregunta","array del módulo array almacena elementos del MISMO tipo","lista es más eficiente para números, concepto diferente al que se describe en esta pregunta","No hay diferencia práctica, aunque algunos enfoques establecen matices al respecto"], correct:1, explanation:"array.array('i', [1,2,3]): array de enteros signed (4 bytes cada uno). list usa ~56 bytes por elemento (overhead de objeto Python).", noShuffle:false },
  { concept_id:"py_u4_q29", unit:4, question:"¿Cómo se implementa una pila (stack) en Python?", options:["Con la clase Stack de Python, concepto diferente al que se describe en esta pregunta","Con una lista y append()/pop() (LIFO: Last In First Out)","Con deque exclusivamente, concepto diferente al que se describe en esta pregunta","Con queue.LifoQueue, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"pila=[]; pila.append(x) (push); pila.pop() (pop). Las listas de Python son eficientes para stacks. deque o queue.LifoQueue para threadsafe.", noShuffle:false },
  { concept_id:"py_u4_q30", unit:4, question:"¿Cómo se implementa una cola (queue) en Python?", options:["Con una lista y append()/pop(0) (ineficiente O(n))","Con collections.deque: appendleft/pop o append/popleft (FIFO O(1))","Con queue.Queue para uso general","Tanto b como c son correctas para distintos casos"], correct:3, explanation:"Lista: pop(0) es O(n). deque.popleft() es O(1). queue.Queue: thread-safe para producción. Para algoritmos simples, deque es la mejor opción.", noShuffle:false },
  { concept_id:"py_u4_q31", unit:4, question:"¿Qué hace itertools.groupby en Python?", options:["Agrupa elementos del iterable por un criterio (clave), devolviendo grupos consecutivos del mismo valor de clave","Ordena y agrupa simultáneamente, concepto diferente al que se describe en esta pregunta","Agrupa todos los elementos iguales sin importar el orden, concepto diferente al que se describe en esta pregunta","Es equivalente a dict.groups(), concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"groupby requiere que el iterable esté ORDENADO por la clave primero. Luego agrupa consecutivos. Útil para procesar datos ya ordenados.", noShuffle:false },
  { concept_id:"py_u4_q32", unit:4, question:"¿Cuál es el orden de los elementos en un set de Python?", options:["Orden de inserción","Orden alfabético","Orden definido por el hash (no determinista desde Python 3.3 con hash randomization)","No tienen orden garantizado: los sets son colecciones no ordenadas"], correct:3, explanation:"Los sets no garantizan orden. Si necesitas un set ordenado, usa dict con claves (mantiene orden en Python 3.7+) o sorted(set(lista)).", noShuffle:false },
  { concept_id:"py_u4_q33", unit:4, question:"¿Qué es dataclasses.dataclass en Python 3.7+?", options:["Una subclase de dict, concepto diferente al que se describe en esta pregunta","Un decorador que genera automáticamente __init__, __repr__","Una forma de crear clases inmutables, concepto diferente al que se describe en esta pregunta","Un tipo de namedtuple con métodos, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"@dataclass class Punto: x:float; y:float. Auto-genera __init__(x,y), __repr__, __eq__. frozen=True para inmutable. Mucho más conciso que definirlos manualmente.", noShuffle:false },
  { concept_id:"py_u4_q34", unit:4, question:"¿Qué hace el método collections.OrderedDict diferente a un dict normal?", options:["Ordena alfabéticamente las claves, concepto diferente al que se describe en esta pregunta","Antes de Python 3.7 garantizaba el orden de inserción. Ahora dict también lo hace, pero OrderedDict tiene operaciones de orden como move_to_end()","Tiene mejor rendimiento, concepto diferente al que se describe en esta pregunta","Solo permite claves de tipo string, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Desde Python 3.7, dict ordinario mantiene orden de inserción. OrderedDict aún tiene ventaja: move_to_end(), popitem(last=False) y comparación sensible al orden.", noShuffle:false },
  { concept_id:"py_u4_q35", unit:4, question:"¿Cómo se puede deduplicar una lista manteniendo el orden de los elementos?", options:["list(set(lista)) (no mantiene orden)","dict.fromkeys(lista) o list(dict.fromkeys(lista))","list(sorted(set(lista))) (cambia el orden)","lista.unique()"], correct:1, explanation:"list(dict.fromkeys(lista)): desde Python 3.7, dict mantiene orden de inserción, eliminando duplicados. Más eficiente que: [x for i,x in enumerate(lista) if x not in lista[:i]].", noShuffle:false },
  { concept_id:"py_u4_q36", unit:4, question:"¿Qué son las 'vistas de memoryview' en Python?", options:["Una forma de visualizar datos en el REPL, concepto diferente al que se describe en esta pregunta","Un objeto que expone el buffer interno de bytes de otro objeto (como bytearray o bytes) sin copiarlos","Una vista del DOM en Python web, concepto diferente al que se describe en esta pregunta","Una representación visual de estructuras de datos, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"memoryview(bytearray) permite acceder/modificar bytes sin copias. Útil para procesamiento de imágenes, vídeo, datos binarios. Evita copias costosas.", noShuffle:false },
  { concept_id:"py_u4_q37", unit:4, question:"¿Cómo se puede invertir una lista in-place en Python?", options:["lista.sort(reverse=True), concepto diferente al que se describe en esta pregunta","lista.reverse() (modifica in-place y devuelve None)","lista = lista[::-1] (crea nueva lista y reasigna)","reversed(lista)"], correct:1, explanation:"lista.reverse(): in-place, O(n), devuelve None. lista[::-1]: crea nueva lista (no in-place). reversed(lista): iterador inverso (no lista).", noShuffle:false },
  { concept_id:"py_u4_q38", unit:4, question:"¿Cuál es la diferencia entre list.sort() y sorted() en términos de estabilidad?", options:["sort() es estable; sorted() no, concepto diferente al que se describe en esta pregunta","Ambos son estables (mantienen el orden relativo de elementos iguales)","sorted() es estable; sort() no, concepto diferente al que se describe en esta pregunta","Ninguno es estable en Python, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Python usa Timsort (O(n log n) worst case, O(n) best case para datos casi ordenados). Es estable: elementos iguales mantienen su orden original.", noShuffle:false },
  { concept_id:"py_u4_q39", unit:4, question:"¿Qué hace 'in' operator con un set versus con una lista?", options:["Son equivalentes en todo, concepto diferente al que se describe en esta pregunta","Con set: O(1) (hash lookup); con lista: O(n) (búsqueda lineal)","Con lista es más rápido, concepto diferente al que se describe en esta pregunta","Con set no se puede usar 'in', concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Si necesitas comprobar pertenencia frecuentemente sobre muchos elementos, convierte la lista a set primero. N búsquedas en lista: O(N*n). En set: O(N).", noShuffle:false },
  { concept_id:"py_u4_q40", unit:4, question:"¿Cómo se puede aplanar una lista de listas en Python?", options:["[x for sublista in listas for x in sublista]","listas.flatten()","list(chain.from_iterable(listas))","Ambas a y c son formas válidas"], correct:3, explanation:"Comprensión: [x for sub in listas for x in sub]. itertools.chain.from_iterable(listas): más eficiente. suma = sum(listas, []) (menos eficiente).", noShuffle:false },
  { concept_id:"py_u4_q41", unit:4, question:"¿Cuál es la estructura de datos más adecuada para implementar un grafo en Python?", options:["Una lista de tuplas","Un diccionario de listas (lista de adyacencia): {nodo: [vecinos]}","Un set de aristas","Una matriz 2D como lista de listas"], correct:1, explanation:"Representaciones de grafo: {nodo:[vecinos]} (lista de adyacencia, eficiente en memoria para grafos dispersos) o numpy matriz (densos). Librería NetworkX para grafos complejos.", noShuffle:false },
  { concept_id:"py_u4_q42", unit:4, question:"¿Qué hace list.count(elemento)?", options:["Devuelve el total de elementos en la lista","Cuenta cuántas veces aparece 'elemento' en la lista","Cuenta los elementos que son mayores que 'elemento'","Devuelve el índice del elemento"], correct:1, explanation:"[1,2,3,2,1].count(2) → 2. Para conteo eficiente de múltiples elementos, usar Counter(lista) que lo hace en una sola pasada O(n).", noShuffle:false },

  // ════════════════════════════════════════════════════════════════
  //  UNIDAD 5 — Ficheros y Entrada/Salida
  // ════════════════════════════════════════════════════════════════
  { concept_id:"py_u5_q1", unit:5, question:"¿Cuál es la forma correcta de abrir un fichero en Python?", options:["file = File.open('ruta')","with open('ruta', 'r') as f:","f = open.read('ruta')","import file; file.open('ruta')"], correct:1, explanation:"with open() as f: gestiona automáticamente el cierre del fichero (context manager). Modos: 'r' lectura, 'w' escritura, 'a' append, 'b' binario.", noShuffle:false },
  { concept_id:"py_u5_q2", unit:5, question:"¿Qué hace f.readlines()?", options:["Lee una sola línea, concepto diferente al que se describe en esta pregunta","Lee todas las líneas y devuelve una lista de strings (incluye \\n al final de cada línea)","Lee el fichero en formato binario, concepto diferente al que se describe en esta pregunta","Lee línea por línea bajo demanda, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"readlines(): ['línea1\\n', 'línea2\\n', ...]. Alternativa más idiomática: for línea in f: (es lazy, no carga todo en memoria).", noShuffle:false },
  { concept_id:"py_u5_q3", unit:5, question:"¿Cuál es la ventaja del 'with' statement para ficheros?", options:["Solo sintáctica, es equivalente a open/close manual, concepto diferente al que se describe en esta pregunta","Garantiza que el fichero se cierra automáticamente aunque haya excepciones (context manager)","Es más rápido que open(), concepto diferente al que se describe en esta pregunta","Permite abrir múltiples ficheros a la vez, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"El context manager llama a f.close() automáticamente en el __exit__, incluso si hay una excepción. Previene resource leaks.", noShuffle:false },
  { concept_id:"py_u5_q4", unit:5, question:"¿Qué hace open('archivo.txt', 'a')?", options:["Crea un nuevo archivo siempre, concepto diferente al que se describe en esta pregunta","Abre en modo append: añade al final sin borrar el contenido existente","Abre en modo lectura-escritura, concepto diferente al que se describe en esta pregunta","Crea el archivo solo si no existe, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Modos: 'r' (read, por defecto), 'w' (write, borra todo), 'a' (append, añade al final), 'x' (create, error si existe), 'r+' (read+write).", noShuffle:false },
  { concept_id:"py_u5_q5", unit:5, question:"¿Cómo se trabaja con ficheros CSV en Python?", options:["import csv; with open('f.csv') as f: reader=csv.reader(f)","Parseando manualmente las comas del string","Solo con pandas, concepto diferente al que se describe en esta pregunta","Con el módulo 'table', concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"csv.reader() para leer, csv.writer() para escribir, csv.DictReader() para obtener dicts con los headers como claves. Pandas pd.read_csv() para análisis de datos.", noShuffle:false },
  { concept_id:"py_u5_q6", unit:5, question:"¿Qué hace json.dump() versus json.dumps() en Python?", options:["Son idénticos, concepto diferente al que se describe en esta pregunta","dump(obj, fichero): escribe JSON en un fichero. dumps(obj): devuelve el JSON como string","dumps escribe en fichero; dump en string, concepto diferente al que se describe en esta pregunta","dump es más seguro que dumps, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"dump: file I/O. dumps: string. Análogamente: load(fichero)→objeto, loads(string)→objeto. 's' en el nombre = string.", noShuffle:false },
  { concept_id:"py_u5_q7", unit:5, question:"¿Qué es el módulo pathlib de Python?", options:["Una librería para gestionar rutas de URL, concepto diferente al que se describe en esta pregunta","Un módulo moderno (Python 3.4+) para trabajar con rutas del sistema de ficheros de forma orientada a objetos","Un módulo para gestionar variables de entorno, concepto diferente al que se describe en esta pregunta","Un cliente de FTP, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"from pathlib import Path; p=Path('dir/file.txt'); p.exists(), p.read_text(), p.write_text(), p.parent, p.stem, p.suffix. Más elegante que os.path.", noShuffle:false },
  { concept_id:"py_u5_q8", unit:5, question:"¿Cómo se maneja una excepción al abrir un fichero que no existe?", options:["Python silencia el error automáticamente","Con try: ... except FileNotFoundError as e:","Con if file.exists() antes de abrir","El modo 'r' crea el fichero si no existe"], correct:1, explanation:"try: with open('f.txt') as f: ... except FileNotFoundError: print('No existe'). También: PermissionError para permisos, IOError como base.", noShuffle:false },
  { concept_id:"py_u5_q9", unit:5, question:"¿Qué hace os.path.join() en Python?", options:["Une dos rutas de URL, concepto diferente al que se describe en esta pregunta","Une componentes de ruta de forma segura y portable (usa / en Linux","Combina el contenido de dos ficheros, concepto diferente al que se describe en esta pregunta","Verifica si una ruta existe, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"os.path.join('/home','user','file.txt')→'/home/user/file.txt'. pathlib.Path('home')/'user'/'file.txt' es la alternativa moderna.", noShuffle:false },
  { concept_id:"py_u5_q10", unit:5, question:"¿Para qué sirve el módulo pickle de Python?", options:["Para gestionar ficheros de imagen, concepto diferente al que se describe en esta pregunta","Para serializar/deserializar objetos Python en formato binario (pickling/unpickling)","Para comprimir ficheros, concepto diferente al que se describe en esta pregunta","Para gestionar variables de entorno, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"pickle.dump(obj, f), pickle.load(f). Serializa cualquier objeto Python. ATENCIÓN: nunca deserializar pickles de fuentes no confiables (vector de ataque).", noShuffle:false },
  { concept_id:"py_u5_q11", unit:5, question:"¿Qué hace el módulo os de Python?", options:["Gestiona el sistema operativo en modo kernel, concepto diferente al que se describe en esta pregunta","Proporciona funciones para interactuar con el sistema operativo: rutas","Solo funciona en Linux, concepto diferente al que se describe en esta pregunta","Es el módulo de E/S de red, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"os.getcwd(), os.listdir(), os.makedirs(), os.environ, os.path.exists(), os.remove(), os.rename(). shutil para copiar/mover ficheros.", noShuffle:false },
  { concept_id:"py_u5_q12", unit:5, question:"¿Cómo se lee un fichero entero como string en Python?", options:["f.read_all()","with open('f.txt') as f: contenido=f.read()","open('f.txt').toString()","Path('f.txt').read_text() (pathlib)"], correct:1, explanation:"f.read(): lee todo. f.read(n): lee n bytes. Alternativa pathlib: Path('f.txt').read_text(encoding='utf-8'). Cuidado con ficheros muy grandes.", noShuffle:false },
  { concept_id:"py_u5_q13", unit:5, question:"¿Cuál es la diferencia entre abrir un fichero en modo 'w' y 'x'?", options:["Son idénticos, concepto diferente al que se describe en esta pregunta","'w' sobreescribe si existe; 'x' lanza FileExistsError si el fichero ya existe (creación exclusiva)","'x' es más rápido que 'w', concepto diferente al que se describe en esta pregunta","'w' crea; 'x' solo escribe en existentes, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"'w': escribe (crea o trunca). 'x': crea nuevo (falla si existe, evita sobreescribir accidentalmente). Disponible desde Python 3.", noShuffle:false },
  { concept_id:"py_u5_q14", unit:5, question:"¿Qué hace f.seek(0) en un objeto de fichero?", options:["Elimina el contenido del fichero, concepto diferente al que se describe en esta pregunta","Mueve el puntero de lectura/escritura al inicio del fichero","Busca el contenido '0' en el fichero, concepto diferente al que se describe en esta pregunta","Cierra y reabre el fichero, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"seek(n) mueve el puntero a la posición n. f.tell() devuelve la posición actual. Útil para leer un fichero varias veces o escribir en posiciones específicas.", noShuffle:false },
  { concept_id:"py_u5_q15", unit:5, question:"¿Para qué se usa el módulo shutil?", options:["Para gestionar shells de sistema, concepto diferente al que se describe en esta pregunta","Para operaciones de alto nivel sobre ficheros: copiar, mover, comprimir","Para streams de red, concepto diferente al que se describe en esta pregunta","Para ejecutar scripts del shell, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"shutil.copy(), shutil.copytree(), shutil.move(), shutil.rmtree(), shutil.make_archive(). Funciones que os no proporciona directamente.", noShuffle:false },
  { concept_id:"py_u5_q16", unit:5, question:"¿Qué hace glob.glob('*.txt')?", options:["Busca texto en ficheros, concepto diferente al que se describe en esta pregunta","Devuelve una lista de rutas de ficheros que coinciden con el patrón (usando wildcards)","Crea múltiples ficheros .txt, concepto diferente al que se describe en esta pregunta","Borra todos los ficheros .txt, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"glob.glob('**/*.py', recursive=True) → todos los .py en subdirectorios. pathlib equivale: Path('.').glob('**/*.py').", noShuffle:false },
  { concept_id:"py_u5_q17", unit:5, question:"¿Cómo se lee un fichero binario (imagen, PDF) en Python?", options:["open('img.png', 'rb') → bytes","open('img.png', 'b')","open('img.png').read_binary()","binary.open('img.png')"], correct:0, explanation:"El modo 'b' (binario) es para ficheros no-texto: imágenes, PDF, Excel. with open('img.png', 'rb') as f: data=f.read() → bytes.", noShuffle:false },
  { concept_id:"py_u5_q18", unit:5, question:"¿Qué hace tempfile.NamedTemporaryFile()?", options:["Crea un fichero con el nombre 'temp', concepto diferente al que se describe en esta pregunta","Crea un fichero temporal con nombre único que se elimina automáticamente al cerrarlo","Crea una carpeta temporal, concepto diferente al que se describe en esta pregunta","Copia el fichero actual a un fichero temporal, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"with tempfile.NamedTemporaryFile(delete=False) as f: ... Útil para tests, cachés temporales. tempfile.mkdtemp() para carpetas temporales.", noShuffle:false },
  { concept_id:"py_u5_q19", unit:5, question:"¿Cómo se pueden leer las variables de entorno del sistema en Python?", options:["env.get('VAR')","import os; os.environ['HOME'] o os.environ.get('VAR','default')","system.getenv('VAR')","env.read('HOME')"], correct:1, explanation:"os.environ es un dict-like de las variables de entorno. .get('VAR','default') devuelve default si no existe. Útil para configuración sin hardcodear credenciales.", noShuffle:false },
  { concept_id:"py_u5_q20", unit:5, question:"¿Qué hace subprocess.run() en Python?", options:["Ejecuta código Python en paralelo, concepto diferente al que se describe en esta pregunta","Ejecuta un comando del sistema operativo y devuelve el resultado","Crea un subproceso de Python, concepto diferente al que se describe en esta pregunta","Ejecuta una función en un hilo nuevo, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"subprocess.run(['ls','-la'], capture_output=True, text=True) → CompletedProcess con stdout, stderr, returncode. Para automatización de sistemas.", noShuffle:false },
  { concept_id:"py_u5_q21", unit:5, question:"¿Cómo se crea un directorio nuevo con pathlib en Python?", options:["os.mkdir('dir')","Path('nuevo_dir').mkdir(parents=True, exist_ok=True)","os.makedirs('nuevo_dir')","Ambas b y c son válidas"], correct:3, explanation:"Path.mkdir(parents=True, exist_ok=True): crea el directorio y todos los necesarios, sin error si ya existe. os.makedirs equivalente antiguo.", noShuffle:false },
  { concept_id:"py_u5_q22", unit:5, question:"¿Qué es el encoding 'utf-8' y por qué es importante al abrir ficheros?", options:["Una forma de comprimir el fichero, concepto diferente al que se describe en esta pregunta","El sistema de codificación de caracteres Unicode estándar","Un modo de apertura de fichero, concepto diferente al que se describe en esta pregunta","El tipo de permisos del fichero, que puede confundirse con este termino en contabilidad general"], correct:1, explanation:"open('f.txt', encoding='utf-8'). Sin encoding, Python usa el encoding del sistema (puede ser diferente en Windows). utf-8 es el estándar moderno para texto.", noShuffle:false },
  { concept_id:"py_u5_q23", unit:5, question:"¿Cómo se puede leer un fichero grande línea por línea sin cargarlo todo en memoria?", options:["file.read() y luego split('\\n'), concepto diferente al que se describe en esta pregunta","for línea in open('grande.txt'): procesar(línea)","file.readlines() con chunk_size, concepto diferente al que se describe en esta pregunta","No es posible en Python, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"El iterador de fichero es lazy: lee una línea a la vez. for línea in f: es la forma idiomática. readline() también lee una línea, pero el bucle es más elegante.", noShuffle:false },
  { concept_id:"py_u5_q24", unit:5, question:"¿Para qué se usa zipfile.ZipFile en Python?", options:["Para comprimir datos en memoria","Para crear, leer y extraer archivos ZIP","Para trabajar con ficheros comprimidos con gzip","Para empaquetar módulos Python"], correct:1, explanation:"with zipfile.ZipFile('arch.zip','w') as zf: zf.write('fichero.txt'). ZipFile('arch.zip','r').extractall('destino'). También tarfile para .tar.gz.", noShuffle:false },
  { concept_id:"py_u5_q25", unit:5, question:"¿Qué devuelve os.listdir(ruta)?", options:["Un generador de rutas absolutas, concepto diferente al que se describe en esta pregunta","Una lista de strings con los nombres de los ficheros y directorios en la ruta dada","Solo ficheros, sin directorios, concepto diferente al que se describe en esta pregunta","Una lista de objetos Path, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"os.listdir('.'): nombres relativos. os.scandir('.'): más eficiente, devuelve DirEntry con atributos. Path('.').iterdir(): pathlib equivalente.", noShuffle:false },
  { concept_id:"py_u5_q26", unit:5, question:"¿Qué hace f.write(string) en Python?", options:["Escribe el string y añade automáticamente \\n, concepto diferente al que se describe en esta pregunta","Escribe el string exactamente tal como es en el fichero y devuelve el número de caracteres escritos","Reemplaza todo el contenido del fichero, concepto diferente al que se describe en esta pregunta","Añade el string al final siempre, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"write() no añade \\n automáticamente. Si lo necesitas: f.write(string + '\\n') o f.write('\\n'.join(líneas)). writelines(lista) escribe una lista de strings.", noShuffle:false },
  { concept_id:"py_u5_q27", unit:5, question:"¿Cómo se puede procesar ficheros XML en Python?", options:["import xml; xml.read('file.xml'), concepto diferente al que se describe en esta pregunta","xml.etree.ElementTree: ET.parse('file.xml').getroot() o lxml para XML más complejo","Solo con librerías de terceros, concepto diferente al que se describe en esta pregunta","Con json.load() si el XML está bien formado, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"import xml.etree.ElementTree as ET; tree=ET.parse('f.xml'); root=tree.getroot(); for child in root: ... También BeautifulSoup para HTML/XML más permisivo.", noShuffle:false },
  { concept_id:"py_u5_q28", unit:5, question:"¿Qué hace logging.basicConfig(level=logging.DEBUG) en Python?", options:["Configura el nivel de depuración del sistema operativo, concepto diferente al que se describe en esta pregunta","Configura el módulo logging para mostrar mensajes de nivel DEBUG y superiores en la consola","Crea un fichero de log automáticamente, concepto diferente al que se describe en esta pregunta","Activa el modo verbose del intérprete de Python, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"El módulo logging es preferible a print() para aplicaciones: niveles (DEBUG, INFO, WARNING, ERROR, CRITICAL), formato configurable, escritura a ficheros.", noShuffle:false },
  { concept_id:"py_u5_q29", unit:5, question:"¿Cómo se puede comprobar si una ruta es un fichero o un directorio?", options:["os.type('ruta'), concepto diferente al que se describe en esta pregunta","os.path.isfile('ruta') y os.path.isdir('ruta') o Path('ruta').is_file() y .is_dir()","file.type('ruta'), concepto diferente al que se describe en esta pregunta","typeof(ruta), concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"os.path.isfile(), os.path.isdir(), os.path.exists(). pathlib: Path('ruta').is_file(), .is_dir(), .exists(), .is_symlink().", noShuffle:false },
  { concept_id:"py_u5_q30", unit:5, question:"¿Para qué sirve el módulo io.StringIO?", options:["Para leer desde la entrada estándar, concepto diferente al que se describe en esta pregunta","Para crear un objeto de fichero en memoria que se comporta como un fichero de texto (útil en tests)","Para convertir strings a IO binario, concepto diferente al que se describe en esta pregunta","Para comprimir strings en memoria, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"import io; f = io.StringIO(); f.write('texto'); f.seek(0); f.read(). Perfecto para tests sin crear ficheros reales. io.BytesIO para binario.", noShuffle:false },
  { concept_id:"py_u5_q31", unit:5, question:"¿Qué información proporciona os.stat('fichero.txt')?", options:["El contenido del fichero, concepto diferente al que se describe en esta pregunta","Metadatos del fichero: tamaño, permisos, timestamps de creación/modificación/acceso","La codificación del fichero, concepto diferente al que se describe en esta pregunta","El número de líneas del fichero, concepto que se aplica en un contexto distinto"], correct:1, explanation:"os.stat() o Path.stat(): st_size (bytes), st_mtime (modificación), st_ctime (creación en Windows, cambio de metadatos en Linux), st_mode (permisos).", noShuffle:false },
  { concept_id:"py_u5_q32", unit:5, question:"¿Cómo se pueden escribir múltiples líneas en un fichero de forma eficiente?", options:["for línea in lista: f.write(línea)","f.writelines(['línea1\\n','línea2\\n']) o f.write('\\n'.join(lista))","f.write(str(lista))","print(*lista, file=f, sep='\\n')"], correct:1, explanation:"writelines() escribe sin añadir \\n. join+write es eficiente. print(*lista, file=f) también funciona. La opción de print sep='\\n' con * es la más pythónica.", noShuffle:false },
  { concept_id:"py_u5_q33", unit:5, question:"¿Cuál es el propósito de configparser en Python?", options:["Para parsear argumentos de línea de comandos, concepto diferente al que se describe en esta pregunta","Para leer y escribir ficheros de configuración en formato INI (secciones","Para analizar ficheros JSON de configuración, concepto diferente al que se describe en esta pregunta","Para gestionar variables de entorno, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"from configparser import ConfigParser; config=ConfigParser(); config.read('app.ini'); config['Base de datos']['host']. Para JSON de configuración: json.load.", noShuffle:false },
  { concept_id:"py_u5_q34", unit:5, question:"¿Qué hace argparse en Python?", options:["Analiza código Python, concepto diferente al que se describe en esta pregunta","Parsea los argumentos de línea de comandos de forma declarativa","Parsea ficheros XML, concepto diferente al que se describe en esta pregunta","Analiza el rendimiento del script, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"import argparse; parser=argparse.ArgumentParser(); parser.add_argument('--fichero'); args=parser.parse_args(); print(args.fichero). Genera help automático.", noShuffle:false },
  { concept_id:"py_u5_q35", unit:5, question:"¿Qué hace os.walk(ruta)?", options:["Camina el proceso Python por el sistema de ficheros, concepto diferente al que se describe en esta pregunta","Genera los nombres de los ficheros en un árbol de directorios de forma recursiva: (dirpath, dirnames, filenames)","Lista solo el primer nivel de directorios, concepto diferente al que se describe en esta pregunta","Busca un fichero por nombre, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"for root, dirs, files in os.walk('.'): for f in files: print(os.path.join(root,f)). pathlib equivale: Path('.').rglob('*').", noShuffle:false },
  { concept_id:"py_u5_q36", unit:5, question:"¿Para qué sirve csv.DictReader en Python?", options:["Lee el CSV como lista de listas, concepto diferente al que se describe en esta pregunta","Lee el CSV como lista de diccionarios usando la primera fila como claves (header)","Lee solo la primera fila del CSV, concepto diferente al que se describe en esta pregunta","Escribe CSV desde un diccionario, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"with open('f.csv') as f: for row in csv.DictReader(f): print(row['nombre']). Mucho más legible que csv.reader con índices numéricos.", noShuffle:false },
  { concept_id:"py_u5_q37", unit:5, question:"¿Qué hace la instrucción 'raise' sin argumentos dentro de un bloque 'except'?", options:["Crea una nueva excepción vacía, concepto diferente al que se describe en esta pregunta","Re-lanza la excepción capturada actualmente (preservando el traceback original)","Sale del bloque except sin hacer nada, concepto diferente al que se describe en esta pregunta","Lanza la última excepción ocurrida en el programa, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"try: ... except Exception as e: log(e); raise  # re-lanza la misma excepción. Útil para logging sin cambiar el comportamiento de error.", noShuffle:false },
  { concept_id:"py_u5_q38", unit:5, question:"¿Qué hace fileinput.input() en Python?", options:["Lee solo un fichero a la vez, concepto diferente al que se describe en esta pregunta","Permite iterar sobre líneas de múltiples ficheros o stdin de forma transparente, como si fuera un solo fichero","Crea un cursor de fichero múltiple, concepto diferente al que se describe en esta pregunta","Lee ficheros de forma inversa, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"import fileinput; for línea in fileinput.input(['f1.txt','f2.txt']): ... O: python script.py *.txt. Útil para scripts de procesamiento de ficheros tipo Unix.", noShuffle:false },
  { concept_id:"py_u5_q39", unit:5, question:"¿Qué hace el modo 'r+' al abrir un fichero?", options:["Solo lectura con permisos root, concepto diferente al que se describe en esta pregunta","Lectura y escritura sin truncar el fichero (el puntero empieza al inicio)","Random access al fichero, concepto diferente al que se describe en esta pregunta","Read y replace: sobreescribe automáticamente, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"'r+': lee y escribe sin borrar (diferente de 'w' que trunca). 'a+': append+read. Con 'r+', seek() permite escribir en posiciones específicas.", noShuffle:false },
  { concept_id:"py_u5_q40", unit:5, question:"¿Para qué sirve el módulo 'dbm' de Python?", options:["Para conectarse a bases de datos relacionales, concepto diferente al que se describe en esta pregunta","Para crear y acceder a bases de datos key-value simples persistentes en ficheros locales","Para gestionar datos en memoria como Redis, concepto diferente al que se describe en esta pregunta","Para analizar ficheros de base de datos SQL, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"import dbm; with dbm.open('mi_bd', 'c') as db: db['clave']='valor'. Base de datos muy simple persistente en disco. Para SQL: sqlite3.", noShuffle:false },
  { concept_id:"py_u5_q41", unit:5, question:"¿Cómo se escribe un número en un fichero de texto en Python?", options:["f.write(numero)","f.write(str(numero))","f.write_number(numero)","print(numero, file=f)"], correct:1, explanation:"write() solo acepta strings. Conversión: f.write(str(42)) o f.write(f'{resultado:.2f}'). print(numero, file=f) también funciona (añade \\n por defecto).", noShuffle:false },
  { concept_id:"py_u5_q42", unit:5, question:"¿Qué hace msvcrt.getch() en Windows / tty en Linux para capturar una tecla sin Enter?", options:["Es estándar Python que funciona en todos los plataformas, concepto diferente al que se describe en esta pregunta","Son módulos específicos de plataforma para leer una tecla sin necesidad de pulsar Enter","Captura todas las teclas del sistema, concepto diferente al que se describe en esta pregunta","No existe tal funcionalidad en Python, si bien existen aproximaciones relacionadas"], correct:1, explanation:"Python no tiene una función multiplataforma para capturar teclas sin Enter. msvcrt.getch() (Windows) o termios+tty (Linux/Mac). La librería keyboard es cross-platform.", noShuffle:false },

  // ════════════════════════════════════════════════════════════════
  //  UNIDAD 6 — Programación Orientada a Objetos en Python
  // ════════════════════════════════════════════════════════════════
  { concept_id:"py_u6_q1", unit:6, question:"¿Cómo se define una clase en Python?", options:["class:NombreClase()","class NombreClase:","object NombreClase()","define NombreClase:"], correct:1, explanation:"class NombreClase: o class NombreClase(ClasePadre): para herencia. El cuerpo es el conjunto de métodos y atributos indentados.", noShuffle:false },
  { concept_id:"py_u6_q2", unit:6, question:"¿Qué es el método __init__ en una clase Python?", options:["El destructor de la clase, concepto que se aplica en un contexto distinto","El constructor: se llama automáticamente cuando se crea una nueva instancia (similar a constructor() en JS)","El método principal de la clase, concepto diferente al que se describe en esta pregunta","Un método especial solo para clases abstractas, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"def __init__(self, params): → inicializa el objeto. self es referencia al objeto creado. No devuelve nada. Se llama: obj = Clase(params).", noShuffle:false },
  { concept_id:"py_u6_q3", unit:6, question:"¿Qué es 'self' en los métodos de una clase Python?", options:["Una palabra reservada del lenguaje que no se puede cambiar, concepto diferente al que se describe en esta pregunta","Una referencia explícita a la instancia actual del objeto (equivalente a 'this' en JS/Java)","El nombre del módulo actual, concepto diferente al que se describe en esta pregunta","El tipo de la clase, que puede confundirse con este termino en contabilidad general"], correct:1, explanation:"self es el primer parámetro de los métodos de instancia. Python lo pasa automáticamente. Técnicamente puede llamarse de otra forma, pero self es la convención.", noShuffle:false },
  { concept_id:"py_u6_q4", unit:6, question:"¿Cómo se hereda de otra clase en Python?", options:["class Hija inherits Padre:","class Hija extends Padre:","class Hija(Padre):","class Hija <- Padre:"], correct:2, explanation:"class Animal: ... class Perro(Animal): ... Perro hereda métodos y atributos de Animal. super().__init__() para llamar al constructor padre.", noShuffle:false },
  { concept_id:"py_u6_q5", unit:6, question:"¿Para qué sirve super() en Python?", options:["Para acceder a variables globales, concepto diferente al que se describe en esta pregunta","Para llamar a métodos de la clase padre en herencia","Para crear una superclase, concepto diferente al que se describe en esta pregunta","Para definir un método como final, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"super().__init__(params) llama al __init__ del padre. super().metodo() llama al método del padre. Necesario en herencia para inicializar correctamente.", noShuffle:false },
  { concept_id:"py_u6_q6", unit:6, question:"¿Qué son los métodos dunder (__dunder__) en Python?", options:["Métodos privados, concepto diferente al que se describe en esta pregunta","Métodos especiales (magic methods) que definen el comportamiento del objeto con operadores y funciones built-in: __str__, __len__, __add__...","Métodos abstractos, concepto diferente al que se describe en esta pregunta","Métodos que solo pueden llamarse una vez, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"__str__: representación string (print). __repr__: representación técnica. __len__: len(). __add__: +. __eq__: ==. __lt__: <. __enter__/__exit__: with.", noShuffle:false },
  { concept_id:"py_u6_q7", unit:6, question:"¿Cuál es la diferencia entre __str__ y __repr__ en Python?", options:["Son lo mismo, concepto diferente al que se describe en esta pregunta","__str__: representación legible para usuarios (print/str())","__repr__ es para listas; __str__ para strings","__str__ es para clases; __repr__ para funciones"], correct:1, explanation:"__str__: Hola, soy Ana. __repr__: Persona(nombre='Ana', edad=25). Si __str__ no existe, Python usa __repr__. En la consola interactiva se muestra __repr__.", noShuffle:false },
  { concept_id:"py_u6_q8", unit:6, question:"¿Qué es la encapsulación en Python?", options:["Guardar un objeto en una cápsula, concepto diferente al que se describe en esta pregunta","Ocultar los detalles internos de implementación. Python usa convenciones: _protegido (convención), __privado (name mangling)","Usar métodos en lugar de atributos, concepto diferente al que se describe en esta pregunta","La herencia de múltiples clases, concepto que se aplica en un contexto distinto"], correct:1, explanation:"Python no tiene modificadores de acceso reales. _var: protegido por convención. __var: name mangling (se convierte en _Clase__var). No hay privacidad real.", noShuffle:false },
  { concept_id:"py_u6_q9", unit:6, question:"¿Qué es el polimorfismo en Python?", options:["Tener múltiples clases, concepto diferente al que se describe en esta pregunta","La capacidad de que objetos de distintas clases respondan al mismo método de forma diferente (sin necesidad de herencia gracias al duck typing)","La herencia múltiple, concepto diferente al que se describe en esta pregunta","Convertir un objeto a otro tipo, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Si dos clases tienen el método area(), se pueden usar intercambiablemente aunque no compartan herencia. Python no requiere interfaces explícitas (duck typing).", noShuffle:false },
  { concept_id:"py_u6_q10", unit:6, question:"¿Python soporta herencia múltiple?", options:["No, solo herencia simple, concepto diferente al que se describe en esta pregunta","Sí: class C(A, B): → C hereda de A y B. El orden de resolución de métodos (MRO) sigue el algoritmo C3","Solo a través de mixins, concepto diferente al que se describe en esta pregunta","Solo con interfaces abstractas, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"MRO (Method Resolution Order): C.mro() muestra el orden de búsqueda. C3 linealización. super() navega el MRO automáticamente.", noShuffle:false },
  { concept_id:"py_u6_q11", unit:6, question:"¿Qué es el MRO (Method Resolution Order) en Python?", options:["El orden en que se ejecutan los métodos dentro de una clase","El orden en que Python busca métodos en la jerarquía de herencia (C3 linearization)","La lista de métodos de una clase, concepto que se aplica en un contexto distinto","El orden de definición de los métodos, concepto que se aplica en un contexto distinto"], correct:1, explanation:"C3 MRO garantiza que cada clase aparece antes que sus padres y antes de sus hermanas. Clase.mro() o __mro__ muestra el orden.", noShuffle:false },
  { concept_id:"py_u6_q12", unit:6, question:"¿Qué son las clases abstractas en Python y cómo se crean?", options:["Clases sin código, concepto diferente al que se describe en esta pregunta","Clases que definen una interfaz mediante ABC (Abstract Base Class) y métodos abstractos que las subclases DEBEN implementar","Clases que no pueden instanciarse porque están incompletas, concepto diferente al que se describe en esta pregunta","Plantillas de clases, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"from abc import ABC, abstractmethod; class Animal(ABC): @abstractmethod def sonido(self): pass. Las subclases deben implementar sonido().", noShuffle:false },
  { concept_id:"py_u6_q13", unit:6, question:"¿Para qué sirven los atributos de clase (vs atributos de instancia)?", options:["Los atributos de clase son más rápidos, concepto que se aplica en un contexto distinto","Los atributos de clase son compartidos por TODAS las instancias","Son equivalentes, concepto diferente al que se describe en esta pregunta","Los de clase son inmutables, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"class Contador: total=0 (clase, compartido). def __init__(self): self.id=Contador.total (instancia, propio). Cuidado con mutables como listas como atributos de clase.", noShuffle:false },
  { concept_id:"py_u6_q14", unit:6, question:"¿Cómo se comprueba si un objeto es instancia de una clase en Python?", options:["obj.isInstance(Clase)","isinstance(obj, Clase)","type(obj) == Clase","obj.__class__ == Clase"], correct:1, explanation:"isinstance(perro, Animal) → True si perro es instancia de Animal o cualquier subclase. type(obj)==Clase: más estricto, no acepta subclases. Preferible isinstance.", noShuffle:false },
  { concept_id:"py_u6_q15", unit:6, question:"¿Qué hace __del__ en Python?", options:["Elimina el objeto inmediatamente, concepto diferente al que se describe en esta pregunta","Es el destructor: se llama cuando el objeto es recolectado por el garbage collector (no siempre determinista)","Define el operador del, concepto diferente al que se describe en esta pregunta","Elimina un atributo del objeto, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"__del__ no es equivalente al destructor C++. No se garantiza cuándo se llama. Usar context managers (with) para gestión de recursos, no __del__.", noShuffle:false },
  { concept_id:"py_u6_q16", unit:6, question:"¿Qué hace __len__ en una clase Python?", options:["Devuelve el número de atributos de la clase, concepto diferente al que se describe en esta pregunta","Permite que len(obj) funcione retornando el tamaño 'semántico' del objeto","Limita el tamaño de la instancia, concepto diferente al que se describe en esta pregunta","Define la longitud máxima de los strings del objeto, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Si defines __len__, len(objeto) llama a __len__. Además, los objetos con __len__=0 son falsy. Implementar __len__ en contenedores personalizados.", noShuffle:false },
  { concept_id:"py_u6_q17", unit:6, question:"¿Qué hace __getitem__ en una clase?", options:["Obtiene el primer elemento","Permite el acceso por índice/clave: obj[clave] llama a __getitem__(self, clave)","Define la key por defecto del objeto","Es equivalente a .get()"], correct:1, explanation:"Con __getitem__ y __setitem__, el objeto se comporta como una colección: obj[0], obj['clave']. __delitem__ para del obj[k].", noShuffle:false },
  { concept_id:"py_u6_q18", unit:6, question:"¿Qué son los mixins en Python?", options:["Errores de herencia múltiple, concepto diferente al que se describe en esta pregunta","Clases diseñadas para añadir funcionalidad específica a otras clases mediante herencia múltiple, sin ser clases base completas","Variables compartidas entre clases, concepto diferente al que se describe en esta pregunta","Métodos de clase especiales, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"class JSONMixin: def to_json(self): return json.dumps(self.__dict__). class Persona(JSONMixin, Base): ... — Persona hereda to_json sin ser una 'JSONBase'.", noShuffle:false },
  { concept_id:"py_u6_q19", unit:6, question:"¿Para qué sirve el método __eq__ en Python?", options:["Para comparar clases, no instancias, concepto diferente al que se describe en esta pregunta","Define el comportamiento del operador ==; sin él, == compara por identidad (como 'is')","Para verificar si el objeto está vacío, concepto diferente al que se describe en esta pregunta","Para comparar longitudes de objetos, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Sin __eq__: obj1==obj2 → False (objetos distintos en memoria). Con __eq__: compara campos. Si defines __eq__, Python deshabilita __hash__ por defecto.", noShuffle:false },
  { concept_id:"py_u6_q20", unit:6, question:"¿Cómo se puede hacer que una clase sea iterable en Python?", options:["Heredar de Iterable, concepto diferente al que se describe en esta pregunta","Implementar __iter__ (devuelve el iterador) y __next__ (devuelve el siguiente elemento y lanza StopIteration al final)","Añadir una lista como atributo, concepto diferente al que se describe en esta pregunta","Con el decorador @iterable, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"def __iter__(self): self.idx=0; return self. def __next__(self): if self.idx>=len(self.data): raise StopIteration; v=self.data[self.idx]; self.idx+=1; return v.", noShuffle:false },
  { concept_id:"py_u6_q21", unit:6, question:"¿Qué hace __contains__ en una clase Python?", options:["Verifica si un método existe en la clase, concepto diferente al que se describe en esta pregunta","Define el operador 'in': 'elemento in objeto' llama a __contains__","Comprueba si la clase contiene otra clase, concepto diferente al que se describe en esta pregunta","Devuelve todos los atributos del objeto, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"class MiSet: def __contains__(self, item): return item in self._datos. Entonces: 'x' in mi_set. Sin __contains__, Python itera el objeto si tiene __iter__.", noShuffle:false },
  { concept_id:"py_u6_q22", unit:6, question:"¿Cuál es la diferencia entre hasattr() y getattr() en Python?", options:["Son equivalentes, concepto diferente al que se describe en esta pregunta","hasattr(obj,'atributo')→True/False; getattr(obj,'atributo',default)→valor o default (sin excepción)","getattr verifica; hasattr obtiene, concepto diferente al que se describe en esta pregunta","Solo funcionan con módulos, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"hasattr: verifica existencia. getattr: obtiene el valor (con default opcional, como dict.get). setattr(obj,'a',v): establece. delattr(obj,'a'): elimina.", noShuffle:false },
  { concept_id:"py_u6_q23", unit:6, question:"¿Qué hace __call__ en una clase Python?", options:["Hace que la clase sea callable (obj() llama al método __call__)","Define cómo se llama al constructor","Es equivalente a __init__","Permite llamar a los métodos de la clase sin instanciar"], correct:0, explanation:"class Contador: def __call__(self): self.n+=1. c=Contador(); c() → incrementa. Útil para decoradores implementados como clases y para objetos función.", noShuffle:false },
  { concept_id:"py_u6_q24", unit:6, question:"¿Qué es el slot (__slots__) en Python?", options:["Una ranura de memoria para la clase, concepto diferente al que se describe en esta pregunta","Una declaración que limita los atributos de instancia a los especificados","Un decorador para métodos estáticos, concepto diferente al que se describe en esta pregunta","Un tipo de herencia restringida, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"class Punto: __slots__=['x','y']. Evita crear __dict__ por instancia (ahorra memoria en millones de objetos). No se pueden añadir atributos dinámicos.", noShuffle:false },
  { concept_id:"py_u6_q25", unit:6, question:"¿Cómo se implementa un Singleton en Python?", options:["class Singleton(single=True):, concepto diferente al que se describe en esta pregunta","Usando __new__ para controlar la creación: si ya existe instancia","Con el decorador @singleton del módulo builtins","No es posible en Python, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"class Singleton: _instancia=None; def __new__(cls): if not cls._instancia: cls._instancia=super().__new__(cls); return cls._instancia. O con módulos (los módulos son singletons).", noShuffle:false },
  { concept_id:"py_u6_q26", unit:6, question:"¿Para qué sirve __getattr__ en Python?", options:["Para obtener todos los atributos del objeto, concepto diferente al que se describe en esta pregunta","Se llama cuando se accede a un atributo que NO EXISTE en el objeto (útil para proxy o lazy loading)","Es equivalente a getattr(), concepto diferente al que se describe en esta pregunta","Se llama antes de buscar cualquier atributo, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"__getattr__ (fallback): solo si el atributo no se encontró normalmente. __getattribute__ (interceptor): se llama SIEMPRE al acceder a cualquier atributo.", noShuffle:false },
  { concept_id:"py_u6_q27", unit:6, question:"¿Cómo se implementa un decorador como clase en Python?", options:["No se pueden implementar decoradores con clases, concepto diferente al que se describe en esta pregunta","class Decorator: def __init__(self,fn): self.fn=fn. def __call__(self,*a,**k): ...; return self.fn(*a,**k)","class Decorator extends Function:, concepto diferente al que se describe en esta pregunta","Heredando de la clase Decorator del módulo functools, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"@MiDecorador equivale a fn=MiDecorador(fn). Al llamar fn(), se llama a MiDecorador.__call__(). Útil cuando el decorador necesita estado.", noShuffle:false },
  { concept_id:"py_u6_q28", unit:6, question:"¿Qué es el patrón Observer implementado en Python?", options:["Una forma de observar el rendimiento, concepto diferente al que se describe en esta pregunta","Un patrón donde objetos (observadores) se suscriben a otro (sujeto) para ser notificados de cambios de estado","Una forma de depurar objetos, concepto diferente al que se describe en esta pregunta","El equivalente de addEventListener en Python, concepto que se aplica en un contexto distinto"], correct:1, explanation:"class Sujeto: _observadores=[]; def suscribir(self,obs): self._observadores.append(obs); def notificar(self): for o in self._observadores: o.actualizar(self).", noShuffle:false },
  { concept_id:"py_u6_q29", unit:6, question:"¿Cómo se puede hacer una clase inmutable en Python?", options:["class MiClase(immutable):, concepto diferente al que se describe en esta pregunta","Usando namedtuple, dataclass(frozen=True) o __setattr__ que lanza AttributeError","Con el decorador @final, concepto diferente al que se describe en esta pregunta","Usando __slots__ sin getter ni setter, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"@dataclass(frozen=True) class Punto: x:float; y:float. punto=Punto(1,2); punto.x=3 → FrozenInstanceError. namedtuple también es inmutable.", noShuffle:false },
  { concept_id:"py_u6_q30", unit:6, question:"¿Qué hace __add__ en una clase?", options:["Añade un atributo al objeto, concepto diferente al que se describe en esta pregunta","Define el comportamiento del operador +: obj1+obj2 llama a obj1.__add__(obj2)","Hace la clase sumable numéricamente, concepto diferente al que se describe en esta pregunta","Es el constructor de suma, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"class Vector: def __add__(self,other): return Vector(self.x+other.x,self.y+other.y). Operadores: __mul__, __sub__, __truediv__, __radd__ (operando derecho), etc.", noShuffle:false },
  { concept_id:"py_u6_q31", unit:6, question:"¿Qué es el protocolo de contexto (context manager protocol)?", options:["Un protocolo de red para Python, concepto diferente al que se describe en esta pregunta","Implementar __enter__ y __exit__ para usar la clase con 'with'","Un protocolo de serialización, concepto diferente al que se describe en esta pregunta","El protocolo de autenticación de Python, concepto que se aplica en un contexto distinto"], correct:1, explanation:"class Connection: def __enter__(self): self.conn=conectar(); return self.conn. def __exit__(self,*args): self.conn.close(). with Connection() as conn: usar(conn).", noShuffle:false },
  { concept_id:"py_u6_q32", unit:6, question:"¿Cómo se define un método abstracto en Python?", options:["abstract def metodo(self):, concepto diferente al que se describe en esta pregunta","@abstractmethod def metodo(self): pass (clase debe heredar de ABC)","def metodo(self) abstract:, concepto diferente al que se describe en esta pregunta","@abstract metodo def(self):, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"from abc import ABC, abstractmethod; class Forma(ABC): @abstractmethod def area(self): pass. La subclase DEBE implementar area() o será también abstracta.", noShuffle:false },
  { concept_id:"py_u6_q33", unit:6, question:"¿Qué es __dict__ en un objeto Python?", options:["El diccionario de todas las clases de Python","El diccionario que almacena los atributos de instancia del objeto","El diccionario de métodos del objeto","El historial de cambios del objeto"], correct:1, explanation:"obj.__dict__ → {'nombre':'Ana', 'edad':25}. vars(obj) es equivalente. Las clases con __slots__ no tienen __dict__ por instancia.", noShuffle:false },
  { concept_id:"py_u6_q34", unit:6, question:"¿Para qué sirve el patrón Strategy en POO con Python?", options:["Para elegir el algoritmo de sorting, concepto diferente al que se describe en esta pregunta","Define una familia de algoritmos intercambiables. Permite seleccionar el algoritmo en tiempo de ejecución sin cambiar el código cliente","Para gestionar el estado de un objeto, concepto diferente al que se describe en esta pregunta","Para crear objetos sin especificar la clase exacta, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"class Ordenador: def __init__(self, estrategia): self.estrategia=estrategia. def ordenar(self,datos): return self.estrategia(datos). Ordenador(sorted).ordenar([3,1,2]).", noShuffle:false },
  { concept_id:"py_u6_q35", unit:6, question:"¿Qué es la composición vs herencia en POO?", options:["Son lo mismo, concepto diferente al que se describe en esta pregunta","Herencia: 'es un'. Composición: 'tiene un'. Composición favorece menor acoplamiento y mayor flexibilidad","Composición es más eficiente siempre, concepto diferente al que se describe en esta pregunta","Herencia permite reutilizar código; composición no, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"'Prefer composition over inheritance' (GoF). Herencia fuerte acoplamiento entre clases. Composición: un Coche HAS-A Motor es más flexible que Coche IS-A Motor.", noShuffle:false },
  { concept_id:"py_u6_q36", unit:6, question:"¿Cómo se puede serializar un objeto Python a JSON?", options:["json.dump(objeto_personalizado) directamente, concepto diferente al que se describe en esta pregunta","Implementando un JSONEncoder personalizado o un método to_dict() y luego json.dumps(obj.to_dict())","Todos los objetos son serializables a JSON, concepto diferente al que se describe en esta pregunta","Con obj.to_json(), concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"json no serializa clases custom. Opciones: to_dict(), default=lambda obj:obj.__dict__, custom JSONEncoder subclass, o librerías como marshmallow/pydantic.", noShuffle:false },
  { concept_id:"py_u6_q37", unit:6, question:"¿Qué hace __hash__ en Python?", options:["Encripta el objeto, concepto diferente al que se describe en esta pregunta","Define la función hash del objeto (necesaria para usar el objeto como clave de dict o elemento de set)","Comprueba la integridad del objeto, concepto diferente al que se describe en esta pregunta","Crea un identificador único para el objeto, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Si defines __eq__, Python deshabilita __hash__ (unhashable). Para objetos inmutables con __eq__: también definir __hash__. hash(obj) = obj.__hash__().", noShuffle:false },
  { concept_id:"py_u6_q38", unit:6, question:"¿Qué son los descriptores en Python?", options:["Documentación automática de clases, concepto diferente al que se describe en esta pregunta","Objetos que definen cómo se accede a atributos de otras clases implementando __get__, __set__ y/o __delete__","Tipos de parámetros decorados, concepto diferente al que se describe en esta pregunta","Una forma especial de herencia, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Los descriptores son el mecanismo detrás de @property, @classmethod, @staticmethod. Una clase con __get__ es un descriptor no-datos; con __get__ y __set__, datos.", noShuffle:false },
  { concept_id:"py_u6_q39", unit:6, question:"¿Cómo se puede obtener la lista de todos los métodos de una clase?", options:["Clase.methods","dir(Clase) o [m for m in dir(Clase) if not m.startswith('_')]","inspect.methods(Clase)","Clase.__methods__"], correct:1, explanation:"dir(obj) lista todos los atributos y métodos (incluidos heredados). vars(Clase) solo los propios. inspect.getmembers(Clase, predicate=inspect.isfunction) para filtrar.", noShuffle:false },
  { concept_id:"py_u6_q40", unit:6, question:"¿Cuál es el propósito del patrón Template Method en Python?", options:["Plantillas de documentación de clases, concepto diferente al que se describe en esta pregunta","Define el esqueleto de un algoritmo en una clase base con algunos pasos abstractos, que las subclases implementan","Genera clases a partir de plantillas, concepto diferente al que se describe en esta pregunta","Define la interfaz de creación de objetos, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"class Juego(ABC): def jugar(self): self.iniciar(); self.bucle(); self.fin(). @abstractmethod def bucle(self): ... Las subclases implementan bucle(). Inversión de control.", noShuffle:false },
  { concept_id:"py_u6_q41", unit:6, question:"¿Qué es una metaclase en Python?", options:["Una clase abstracta avanzada","Una clase cuyas instancias son clases (type es la metaclase por defecto de todas las clases Python)","Una clase para bases de datos","Una superclase de todas las clases"], correct:1, explanation:"type('MiClase', (Base,), {'metodo': fn}) crea una clase dinámicamente. Las metaclases personalizan la creación de clases. Avanzado: Django ORM, SQLAlchemy usan metaclases.", noShuffle:false },
  { concept_id:"py_u6_q42", unit:6, question:"¿Cuál es la diferencia entre shallow copy y deep copy en objetos Python?", options:["Son equivalentes, concepto diferente al que se describe en esta pregunta","Shallow: copia el objeto pero las referencias internas siguen apuntando a los mismos objetos. Deep: copia recursivamente todo el objeto y sus subobjetos","Shallow es más profunda que deep, concepto diferente al que se describe en esta pregunta","Deep solo funciona con listas, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"import copy; copy.copy(obj) → shallow. copy.deepcopy(obj) → deep (copia completa recursiva). Para objetos simples sin referencias internas, shallow es suficiente.", noShuffle:false },
];
